INSERT INTO ccd_indicators (master_ik,master_id,ik_id,indikator,satuan,baseline,t1,t2,t3,t4,t5,iku_alasan,iku_formulasi,iku_tipehitung, iku_do, iku_sumberdata, iku_penjab) VALUES
('01-00-00-00-00-01','01-00-00-00-00','01','Rata rata lama sekolah','Persen','','6.89','6.9','6.91','6.92','6.93','Dalam perencanaan pembangunan daerah, RLS merupakan salah satu komponen pembentuk Indeks Pembangunan Manusia (IPM) dan menjadi indikator penting untuk mengevaluasi keberhasilan pembangunan sektor pendidikan.','Rata-Rata Lama Sekolah (RLS)=Jumlah Penduduk Usia ≥ 25 Tahun : Lama Sekolah Penduduk Usia ≥ 25 Tahun​','Kumulatif','Rata-Rata Lama Sekolah (RLS) adalah rata-rata jumlah tahun pendidikan formal yang telah berhasil diselesaikan oleh penduduk berusia 25 tahun ke atas pada suatu wilayah dalam periode tertentu. Indikator ini menggambarkan tingkat pencapaian pendidikan penduduk berdasarkan jenjang pendidikan tertinggi yang telah ditamatkan, bukan pendidikan yang sedang ditempuh.RLS digunakan sebagai salah satu indikator utama untuk mengukur kualitas sumber daya manusia di bidang pendidikan. Semakin tinggi nilai RLS, semakin tinggi pula tingkat pendidikan yang telah dicapai oleh penduduk suatu daerah. Sebaliknya, nilai RLS yang rendah menunjukkan bahwa sebagian besar penduduk hanya menyelesaikan pendidikan pada jenjang yang lebih rendah atau tidak menamatkan pendidikan formal.','BPS','Badan Pusat Statistik (BPS) sebagai penyedia data resmi.'),
('01-00-00-00-00-02','01-00-00-00-00','02','Harapan Lama Sekolah','Persen','','11.85','11.86','11.87','11.88','11.89','HLS merupakan indikator outcome (hasil) yang mencerminkan keberhasilan pembangunan pendidikan secara jangka panjang. Nilai HLS yang tinggi menunjukkan semakin besar peluang anak usia sekolah untuk melanjutkan pendidikan ke jenjang yang lebih tinggi, sedangkan nilai HLS yang rendah menunjukkan masih terbatasnya akses atau keberlanjutan pendidikan.','Harapan Lama Sekolah=∑Angka Partisipasi Sekolah menurut kelompok umur.','Kumulatif','','BPS',''),
('01-00-00-00-00-03','01-00-00-00-00','03','Persentase lembaga kepemudaan dan Olahraga yang aktif','Persen','','71.43','71.63','71.83','71.93','71.95','Indikator "Persentase Lembaga Kepemudaan dan Olahraga yang Aktif" dipilih karena mampu menggambarkan tingkat keberhasilan pemerintah daerah dalam membina, memberdayakan, dan menjaga keberlangsungan organisasi kepemudaan dan olahraga sebagai mitra strategis pembangunan. Indikator ini tidak hanya mengukur jumlah organisasi yang terdaftar, tetapi juga mengukur sejauh mana organisasi tersebut benar-benar menjalankan fungsinya','(Jumlah lembaga kepemudaan dan olahraga yang aktif ÷ Jumlah seluruh lembaga kepemudaan dan olahraga yang terdaftar) × 100%','Kumulatif','Persentase lembaga kepemudaan dan olahraga yang masih menjalankan fungsi organisasi secara aktif melalui kegiatan, tata kelola organisasi, dan partisipasi dalam pembinaan kepemudaan dan/atau olahraga selama periode pengukuran dibandingkan dengan jumlah seluruh lembaga kepemudaan dan olahraga yang terdaftar di wilayah administrasi yang sama. Lembaga dinyatakan aktif apabila memenuhi paling sedikit 4 dari 5 kriteria berikut: (1) memiliki kepengurusan yang masih berlaku dan berfungsi; (2) melaksanakan minimal dua kegiatan kepemudaan dan/atau olahraga dalam satu tahun; (3) memiliki sekretariat atau alamat yang dapat diverifikasi; (4) menyampaikan laporan kegiatan atau terdokumentasi dalam sistem pelaporan instansi pembina; (5) berpartisipasi dalam kegiatan pembinaan, pelatihan, kompetisi, atau program yang diselenggarakan pemerintah atau mitra dalam satu tahun terakhir.','Bidang Kepemudaan dan Olahraga','Dindikpora Kab. Banjarnegara'),
('01-00-00-00-00-04','01-00-00-00-00','04','Presentase pemuda pelopor yang berhasil menjadi inovator','Persen','','59','63','65','67','69','Indikator ini dipilih untuk mengetahui jumlah pemuda pelopor yang berhasil menjadi inovator dibidangnya','(Jumlah Pemuda Pelopor usia 16-30 tahun yang memenuhi kriteria inovator ÷ Jumlah seluruh Pemuda Pelopor usia 16-30 tahun) × 100%','Kumulatif','Persentase penerima penghargaan atau peserta program Pemuda Pelopor yang berhasil menghasilkan, mengembangkan, dan/atau menerapkan suatu inovasi yang memberikan manfaat nyata bagi masyarakat, organisasi, dunia usaha, atau pemerintah dalam periode satu tahun. Inovasi telah diterapkan minimal satu kali dalam kondisi nyata.Memberikan manfaat nyata bagi masyarakat, organisasi, atau sektor usaha.Inovasi masih berjalan atau memiliki rencana pengembangan yang jelas. Tersedia dokumen pendukung, foto, video, publikasi, penghargaan, atau laporan implementasi','Bidang Kepemudaan dan Olahraga','Dindikpora Kab. Banjarnegara'),
('01-01-00-00-00-01','01-01-00-00-00','01','Angka Partisipasi Kasar (APK) jenjang PAUD, SD, SMP','Persen','94.05','100','100','100','100','100','APK mengukur kapasitas sistem pendidikan dalam menampung peserta didik pada suatu jenjang. Nilai APK dapat mencapai atau bahkan melebihi 100% apabila terdapat peserta didik yang berusia lebih muda atau lebih tua dari usia resmi jenjang tersebut.','Jumlah Peserta Didik pada jenjang PAUD, SD sederajat dan SMP sederajat Dibagi Jumlah Penduduk Usia Sekolah (5 – 15 tahun) Kabupaten/kota tersebut x100%','Kumulatif','Pembilang : Jumlah anak usia 5-15 tahun yang sedang mengikuti pendidikan anak usia dini, Sekolah Dasar, Sekolah Menengah baik negeri maupun swasta (kelompok bermain, raudhatul athfal, taman kanak-kanak, satuan paud sejenis, dan Taman Pendidikan Al-Qur`an, Sekolah Dasar negeri dan Swasta, SMP negeri dan Swata ) dalam kurun waktu 1 tahun anggaran pada tahun ajaran baru di daerah kabupaten/kota. Penyebut : Jumlah keseluruhan penduduk (anak) berusia 5-15 tahun di daerah kabupaten/kota yang bersangkutan sesuai dengan data kependudukan.','Aplikasi Dapodik, data Dindukcapil, data emis kemenag','Dindikpora Kab. Banjarnegara'),
('01-01-00-00-00-02','01-01-00-00-00','02','Angka Partisipasi Murni (APM) jenjang PAUD, SD, SMP','Persen','76.45','84.3','88.5','92.9','97.6','100','APM untuk mengukur tingkat partisipasi penduduk usia sekolah yang mengikuti pendidikan sesuai dengan jenjang berdasarkan usia resminya. APM hanya menghitung peserta didik yang usianya sesuai dengan jenjang pendidikan yang diikuti.','Jumlah Penduduk usia 5-15 tahun yang bersekolah dijenjang Pendidikan PAUD, SD dan SMP pada kabupaten tersebut dibagi jumlah Penduduk usia 5– 15 Tahun di Kabupaten kota tersebut x 100%','Kumulatif','','Aplikasi Dapodik, data Dindukcapil, data emis kemenag','Dinas Pendidikan, Kepemudaan dan Olahraga'),
('01-01-00-00-00-03','01-01-00-00-00','03','Indeks Capaian Standar Pelayanan Minimal (SPM) Pendidikan','Persen','100','100','100','100','100','100','indeks capaian standar pelayanan minimal pendidikan Mengukur pemenuhan kewajiban pelayanan dasar. SPM merupakan urusan wajib yang harus dipenuhi pemerintah daerah sehingga indeks ini mencerminkan tingkat kepatuhan terhadap standar pelayanan yang ditetapkan. Menggambarkan kualitas layanan pendidikan, tidak hanya mengukur jumlah penerima layanan, tetapi juga kesesuaian pelayanan dengan standar yang telah ditetapkan, Mendukung evaluasi kinerja pemerintah daerah. Hasil pengukuran dapat digunakan untuk menilai efektivitas penyelenggaraan pelayanan dasar pendidikan.','Nilai yang dikeluarkan dari Rapor Pendidikan berdasarkan perhitungan hasil ANBK','Kumulatif','','Aplikasi bangda e-kemendagri, Rapor Pendidikan didasarkan pada Peraturan Pemerintah Permendikbudristek Nomor 32 Tahun 2022 tentang Standar Teknis Pelayanan Minimal Pendidikan','Dinas Pendidikan, Kepemudaan dan Olahraga'),
('01-01-01-00-00-01','01-01-01-00-00','01','persentase Anak Tidak Sekolah (ATS)','Persen','                                                                                  ','7.66935572991491','7.27','6.77','6.27','5.77','Indikator ini digunakan untuk mengukur tingkat keterjangkauan dan pemerataan akses layanan pendidikan serta mengidentifikasi jumlah anak usia sekolah yang belum memperoleh hak atas pendidikan. Semakin rendah nilai indikator ATS, semakin baik akses dan pemerataan layanan pendidikan di suatu daerah. Indikator ini digunakan untuk mengetahui jumlah Anak Tidak Sekolah (ATS) yang melanjutkan ke PKBM','Jumlah Anak Tidak Sekolah dibagi jumlah siswa APS * 100% (data ats keseluruhan berdasarkan dapodik akhir tahun (Desember)','Kumulatif','Jumlah anak usia sekolah yang tidak terdaftar sebagai peserta didik aktif pada pendidikan formal (SD/MI, SMP/MTs, atau sederajat) maupun pendidikan kesetaraan (Paket A, Paket B, atau Paket C), berdasarkan hasil pemadanan data dan verifikasi (data ATS, DO(Drop Out) dan LTM(Lulus Tidak Melanjutkan) dibagi jumlah Angka Partisipasi Sekolah di akhir tahun dikali 100%. Bersarkan Pedum LPPD','Data Dapodik, data Kependudukan dari Capil','Kepala Bidang'),
('01-01-01-01-00-01','01-01-01-01-00','01','Persentase Jumlah anak usia 5-6 tahun yang berpartisipasi dalam pendidikan dasar (APS)','Persen','72.19','85.15','85.93','86.71','87.49','88.27','Indikator Persentase Jumlah Anak Usia 5–6 Tahun yang Berpartisipasi dalam Pendidikan Dasar (APS) dipilih karena memiliki beberapa pertimbangan sebagai berikut:Mengukur akses awal terhadap pendidikan dasar.Indikator ini menunjukkan sejauh mana anak usia 5–6 tahun telah memperoleh kesempatan mengikuti pendidikan dasar, sehingga dapat digunakan untuk menilai keterjangkauan layanan pendidikan pada usia awal.Mendukung peningkatan akses pendidikan yang inklusif.APS menjadi ukuran keberhasilan pemerintah daerah dalam membuka akses pendidikan bagi seluruh anak, termasuk anak yang telah memenuhi persyaratan untuk memasuki SD lebih awal sesuai ketentuan yang berlaku.Menjadi dasar identifikasi anak yang belum memperoleh layanan pendidikan dasar.','APS Usia 5–6 Tahun=Jumlah seluruh penduduk usia 5–6 tahundibagi Jumlah anak usia 5–6 tahun yang bersekolah ×100%','Kumulatif','Persentase Jumlah Anak Usia 5–6 Tahun yang Berpartisipasi dalam Pendidikan Dasar (APS) adalah persentase penduduk berusia 5–6 tahun yang tercatat sebagai peserta didik aktif pada jenjang pendidikan dasar, yaitu Sekolah Dasar (SD) atau bentuk lain yang sederajat, dibandingkan dengan seluruh jumlah penduduk usia 5–6 tahun pada wilayah tertentu dalam periode pengukuran.','Data Dapodik dan data Penduduk bersumber pada Capil','Bidang PAUD Dikmas'),
('01-01-01-01-00-02','01-01-01-01-00','02','persentase Peningkatan Proporsi Jumlah satuan PAUD yang Mendapatkan Minimal Akreditasi B','Persen','','73.83','73.96','73.98','74','74.02','Indikator ini digunakan untuk mengukur tingkat partisipasi anak usia dini yang telah memasuki pendidikan dasar, baik sesuai ketentuan usia maupun melalui percepatan masuk sekolah berdasarkan kebijakan yang berlaku. Indikator ini digunakan untuk mengukur keberhasilan pemerintah daerah dalam meningkatkan mutu layanan PAUD melalui peningkatan jumlah satuan PAUD yang memenuhi standar mutu nasional sebagaimana dibuktikan dengan hasil akreditasi minimal peringkat B.','Jumlah PAUD yang mendapatkan akreditasi B dibagi jumlah PAUD dikali 100%','Kumulatif','Persentase Peningkatan Proporsi Jumlah Satuan PAUD yang Mendapatkan Minimal Akreditasi B adalah persentase peningkatan proporsi satuan Pendidikan Anak Usia Dini (PAUD) yang telah memperoleh hasil akreditasi minimal peringkat B (B atau A) dibandingkan dengan seluruh satuan PAUD yang telah terakreditasi pada tahun berjalan, dibandingkan dengan proporsi pada tahun sebelumnya.','Data Dapodik','Bidang PAUD Dikmas'),
('01-01-01-01-01-01','01-01-01-01-01','01','Jumlah Sarana, Prasarana dan Utilitas PAUD','Unit','11','12','13','14','15','15','Indikator ini digunakan untuk mengukur ketersediaan dan pemenuhan fasilitas pendukung pembelajaran sehingga proses pendidikan dapat berlangsung secara aman, nyaman, sehat, dan sesuai dengan Standar Nasional Pendidikan (SNP) serta Standar Pelayanan Minimal (SPM) bidang pendidikan.','Jumlah Sarana, Prasarana dan Utilitas PAUD yang Telah Dibangun','Kumulatif','Jumlah Sarana, Prasarana, dan Utilitas PAUD adalah jumlah keseluruhan sarana, prasarana, dan utilitas yang tersedia dan memenuhi ketentuan untuk mendukung penyelenggaraan layanan pendidikan pada satuan Pendidikan Anak Usia Dini (PAUD), baik yang berasal dari pembangunan baru, rehabilitasi, pengadaan, maupun peningkatan kualitas, dalam periode pelaporan tertentu.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-01-02-01','01-01-01-01-02','01','Jumlah Perlengkapan Peserta Didik PAUD yang tersedia','Unit','5','2','3','4','5','6','Indikator ini digunakan untuk mengukur tingkat ketersediaan perlengkapan yang dapat digunakan secara langsung oleh peserta didik dalam mendukung proses pembelajaran dan tumbuh kembang anak usia dini.','Jumlah Perlengkapan Peserta Didik PAUD yang Tersedia','Kumulatif','Jumlah Perlengkapan Peserta Didik PAUD yang Tersedia adalah jumlah keseluruhan perlengkapan yang disediakan oleh satuan Pendidikan Anak Usia Dini (PAUD) atau Pemerintah Daerah untuk mendukung kegiatan belajar, bermain, pengembangan karakter, kesehatan, keamanan, dan kenyamanan peserta didik sesuai dengan standar pelayanan pendidikan pada periode pelaporan tertentu.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-01-03-01','01-01-01-01-03','01','Jumlah Pendidik dan Tenaga Kependidikan yang Mendapatkan Fasilitasi Kenaikan Pangkat/Golongan, Pemberian Promosi, Peningkatan Kompetensi dan Kualifikasi','Orang','1162','1170','1180','1190','1200','1210','Indikator ini mengukur cakupan layanan pembinaan dan pengembangan sumber daya manusia di bidang pendidikan sebagai upaya meningkatkan profesionalisme pendidik dan tenaga kependidikan.','Jumlah Pendidik dan Tenaga Kependidikan yang Mendapatkan Fasilitasi Kenaikan Pangkat/Golongan, Pemberian Promosi, Peningkatan Kompetensi dan Kualifikasi','Kumulatif','Jumlah Pendidik dan Tenaga Kependidikan yang Mendapatkan Fasilitasi Kenaikan Pangkat/Golongan, Pemberian Promosi, Peningkatan Kompetensi, dan Kualifikasi adalah jumlah pendidik dan tenaga kependidikan pada satuan pendidikan yang memperoleh fasilitasi dari pemerintah daerah atau instansi berwenang dalam bentuk layanan administrasi, pembinaan, pelatihan, pendidikan lanjutan, sertifikasi, atau bentuk dukungan lainnya yang bertujuan untuk meningkatkan jenjang karier, kompetensi, dan kualifikasi akademik selama periode pelaporan.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-01-04-01','01-01-01-01-04','01','Jumlah PAUD yang Mengelola Dana BOP','Peserta Didik','710','701','701','701','701','701','Indikator ini digunakan untuk mengukur cakupan satuan PAUD yang telah melaksanakan pengelolaan Dana BOP secara administratif dan sesuai dengan petunjuk teknis yang berlaku.','jumlah pengelolaan dana BOP PAUD','Kumulatif','Jumlah PAUD yang Mengelola Dana BOP adalah jumlah satuan Pendidikan Anak Usia Dini (PAUD) yang menerima dan mengelola Dana Bantuan Operasional Penyelenggaraan (BOP) PAUD sesuai dengan ketentuan peraturan perundang-undangan pada periode pelaporan tertentu. Pengelolaan Dana BOP meliputi kegiatan perencanaan, penggunaan, penatausahaan, pelaporan, dan pertanggungjawaban dana untuk mendukung operasional penyelenggaraan layanan pendidikan.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-01-05-01','01-01-01-01-05','01','Jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang Pendidikan yang dilaksanakan','Dokumen','1','3','3','3','3','3','Untuk mengetahui jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang pendidikan','Jumlah kegiatan sosialisasi dan advokasi kebijakan dibidang pendidikan','Kumulatif','Jumlah Kegiatan Sosialisasi dan Advokasi Kebijakan di Bidang Pendidikan yang Dilaksanakan adalah jumlah kegiatan yang telah diselenggarakan oleh Dinas Pendidikan atau instansi yang berwenang dalam rangka menyampaikan, menjelaskan, mempromosikan, mengoordinasikan, dan mengadvokasi kebijakan, program, atau regulasi di bidang pendidikan kepada pemangku kepentingan (stakeholders) selama periode pelaporan.Kegiatan sosialisasi bertujuan meningkatkan pemahaman para pemangku kepentingan terhadap kebijakan pendidikan, sedangkan advokasi bertujuan memperoleh dukungan, komitmen, serta partisipasi aktif dalam pelaksanaan kebijakan dan program pendidikan. Indikator ini mengukur jumlah kegiatan yang telah dilaksanakan, bukan jumlah peserta yang mengikuti kegiatan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-01-06-01','01-01-01-01-06','01','Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Orang','100','100','100','100','100','100','Kegiatan ini dapat ditujukan kepada pendidik, tenaga kependidikan, pengawas sekolah, penilik, pengelola satuan pendidikan, maupun pihak lain yang terlibat dalam penyelenggaraan pendidikan. Indikator ini mengukur jumlah kegiatan yang telah dilaksanakan','Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Kumulatif','Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan adalah kegiatan pengembangan kompetensi yang diselenggarakan oleh Dinas Pendidikan atau instansi yang berwenang dalam bentuk bimbingan teknis (bimtek), pelatihan, magang, dan/atau praktik kerja lapangan (PKL) guna meningkatkan pengetahuan, keterampilan, sikap profesional, dan kapasitas sumber daya manusia di bidang pendidikan sesuai dengan tugas, fungsi, dan kebutuhan penyelenggaraan layanan pendidikan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-01-07-01','01-01-01-01-07','01','Jumlah Sarana, Prasarana dan Utilitas PAUD yang Telah Direhabilitasi Sedang/Berat','Unit','22','25','26','27','28','29','Indikator ini digunakan untuk mengukur capaian pelaksanaan rehabilitasi fasilitas PAUD dalam rangka meningkatkan kualitas lingkungan belajar yang aman, sehat, dan layak bagi peserta didik.','Jumlah Sarana, Prasarana dan Utilitas PAUD yang Telah Direhabilitasi Sedang/Berat','Kumulatif','Jumlah Sarana, Prasarana, dan Utilitas PAUD yang Telah Direhabilitasi Sedang/Berat adalah jumlah sarana, prasarana, dan utilitas pada satuan Pendidikan Anak Usia Dini (PAUD) yang telah selesai direhabilitasi dengan tingkat kerusakan sedang atau berat sehingga kembali memenuhi standar kelayakan fungsi, keamanan, kenyamanan, dan mendukung penyelenggaraan layanan pendidikan sesuai ketentuan yang berlaku dalam periode pelaporan.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-01-08-01','01-01-01-01-08','01','Jumlah Alat Praktik dan Peraga PAUD yang Tersedia','Paket','3','4','5','6','7','8','Indikator ini digunakan untuk mengukur tingkat ketersediaan media pembelajaran dan alat praktik yang mendukung terciptanya proses pembelajaran yang aktif, kreatif, inovatif, menyenangkan, dan sesuai dengan karakteristik perkembangan anak usia dini.','Jumlah Alat Praktek dan Peraga PAUD yang Tersedia','Kumulatif','Jumlah Alat Praktik dan Peraga PAUD yang Tersedia adalah jumlah unit alat praktik dan alat peraga edukatif yang tersedia dalam kondisi baik dan layak digunakan pada satuan Pendidikan Anak Usia Dini (PAUD) untuk mendukung proses pembelajaran, bermain sambil belajar, serta pengembangan seluruh aspek perkembangan anak sesuai dengan kurikulum dan Standar Nasional Pendidikan (SNP) pada periode pelaporan. Alat praktik dan peraga yang dihitung merupakan barang yang dimiliki, diterima melalui pengadaan pemerintah, bantuan, hibah, atau pengadaan mandiri oleh satuan PAUD, telah tercatat dalam administrasi inventaris (apabila merupakan aset), dan dapat dimanfaatkan secara langsung dalam kegiatan pembelajaran.Alat praktik dan peraga yang dihitung merupakan barang yang dimiliki, diterima melalui pengadaan pemerintah, bantuan, hibah, atau pengadaan mandiri oleh satuan PAUD, telah tercatat dalam administrasi inventaris (apabila merupakan aset), dan dapat dimanfaatkan secara langsung dalam kegiatan pembelajaran.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-02-00-01','01-01-01-02-00','01','Persentase ATS yang melanjutkan ke PKBM','Persen','','38','38.5','39','39.5','40','Indikator ini digunakan untuk mengukur keberhasilan pemerintah daerah dalam meningkatkan akses layanan pendidikan nonformal bagi ATS melalui penyelenggaraan pendidikan kesetaraan di PKBM.','jumlah ats yang telah terdaftar pada PKBM, mengikuti pendidikan kesetaraan (Paket A, Paket B, atau Paket C); dan berstatus peserta didik aktif pada tahun pengukuran dibagi dengan Jumlah seluruh ATS yang menjadi sasaran penanganan pemerintah daerah berdasarkan hasil pendataan pada tahun yang sama x 100%','Kumulatif','Persentase Anak Tidak Sekolah (ATS) yang Melanjutkan ke PKBM adalah persentase anak usia sekolah yang sebelumnya berstatus Anak Tidak Sekolah (ATS) dan berhasil didaftarkan serta menjadi peserta didik aktif pada Pusat Kegiatan Belajar Masyarakat (PKBM) melalui program pendidikan kesetaraan (Paket A, Paket B, atau Paket C) pada tahun berjalan, dibandingkan dengan jumlah seluruh ATS yang menjadi sasaran penanganan oleh pemerintah daerah pada periode yang sama','Data Dapodik','Bidang PAUD Dikmas'),
('01-01-01-02-01-01','01-01-01-02-01','01','Jumlah Peserta Didik Nonformal/Kesetaraan yang Menerima Biaya Personil Peserta Didik','Peserta Didik',' NA','585','585','585','585','585','Indikator ini digunakan untuk mengukur cakupan layanan bantuan biaya personal yang diterima oleh peserta didik pendidikan nonformal dan pendidikan kesetaraan sebagai upaya meningkatkan akses, pemerataan, dan keberlangsungan layanan pendidikan.','Jumlah Peserta Didik non formal kesetaraan yang menerima biaya personil peserta didik','Kumulatif','Jumlah Peserta Didik Nonformal/Kesetaraan yang Menerima Biaya Personil Peserta Didik adalah jumlah peserta didik yang terdaftar dan aktif mengikuti program pendidikan nonformal atau pendidikan kesetaraan pada lembaga yang sah, serta menerima bantuan biaya personal dari pemerintah pusat, pemerintah daerah, atau sumber pendanaan lain yang sah selama periode pelaporan. Biaya personil peserta didik adalah bantuan yang diberikan secara langsung kepada peserta didik untuk membantu memenuhi kebutuhan pribadi yang berkaitan dengan proses pembelajaran sehingga peserta didik dapat mengikuti pendidikan secara berkelanjutan dan menyelesaikan program pendidikannya.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-02-02-01','01-01-01-02-02','01','Jumlah Sekolah Non Formal/Kesetaraan yang Dilaksanakan Pembinaan Kelembagaan danManajemen','Satuan Pendidikan','7','25','25','25','25','25','Indikator ini digunakan untuk mengukur cakupan satuan pendidikan nonformal/kesetaraan yang telah memperoleh layanan pembinaan kelembagaan dan manajemen dari pemerintah daerah.','Jumlah Sekolah Non Formal/Kesetaraan yang Dilaksanakan Pembinaan Kelembagaan dan Manajemen','Kumulatif','Jumlah Satuan Pendidikan Nonformal/Kesetaraan yang Dilaksanakan Pembinaan Kelembagaan dan Manajemen adalah jumlah satuan pendidikan nonformal dan pendidikan kesetaraan yang memperoleh kegiatan pembinaan dari Dinas Pendidikan atau instansi yang berwenang dalam rangka meningkatkan kapasitas kelembagaan, tata kelola, administrasi, mutu layanan, dan manajemen penyelenggaraan pendidikan selama satu periode pelaporan. Pembinaan kelembagaan dan manajemen merupakan serangkaian kegiatan pendampingan, pembinaan, supervisi, monitoring, evaluasi, konsultasi, bimbingan teknis, atau fasilitasi yang bertujuan meningkatkan kemampuan lembaga dalam mengelola penyelenggaraan pendidikan sesuai dengan ketentuan peraturan perundang-undangan dan standar yang berlaku.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-02-03-01','01-01-01-02-03','01','Jumlah Sekolah Non Formal/Kesetaraan yangMengelola Dana BOP','Satuan Pendidikan','21','25','25','25','25','25','Indikator ini digunakan untuk mengukur cakupan satuan pendidikan nonformal/kesetaraan yang telah melaksanakan pengelolaan Dana BOP secara tertib, akuntabel, transparan, dan sesuai ketentuan.','Jumlah Sekolah Non Formal/Kesetaraan yang Mengelola Dana BOP','Kumulatif','Jumlah Satuan Pendidikan Nonformal/Kesetaraan yang Mengelola Dana BOP adalah jumlah satuan pendidikan nonformal dan pendidikan kesetaraan yang menerima Dana Bantuan Operasional Penyelenggaraan (BOP) dan melaksanakan pengelolaan dana tersebut sesuai dengan ketentuan peraturan perundang-undangan pada periode pelaporan. Pengelolaan Dana BOP meliputi seluruh tahapan pengelolaan keuangan, mulai dari perencanaan, pelaksanaan penggunaan dana, penatausahaan, pelaporan, hingga pertanggungjawaban, sesuai dengan petunjuk teknis yang berlaku.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-02-04-01','01-01-01-02-04','01','Peningkatan Kapasitas Pengelolaan Dana BOP Sekolah Nonformal/Kesetaraan','Orang',' NA','290','290','290','290','290','Indikator ini mengukur jumlah kegiatan atau jumlah peserta yang memperoleh peningkatan kapasitas, sesuai dengan definisi yang ditetapkan dalam dokumen perencanaan.','Jumlah Sekolah yang menerima Peningkatan Kapasitas Pengelolaan Dana BOP Sekolah Nonformal/Kesetaraan','Kumulatif','Peningkatan Kapasitas Pengelolaan Dana BOP Sekolah Nonformal/Kesetaraan adalah kegiatan yang diselenggarakan atau difasilitasi oleh Dinas Pendidikan atau instansi yang berwenang untuk meningkatkan pengetahuan, keterampilan, dan kemampuan pengelola Dana Bantuan Operasional Penyelenggaraan (BOP) pada satuan pendidikan nonformal/kesetaraan dalam melaksanakan pengelolaan dana secara efektif, efisien, transparan, akuntabel, dan sesuai dengan ketentuan peraturan perundang-undangan','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-02-05-01','01-01-01-02-05','01','Jumlah Peserta Didik yang Mengikuti ProsesBelajar','Peserta Didik','6132','585','585','585','585','585','Indikator ini digunakan untuk mengukur jumlah peserta didik yang memperoleh layanan pembelajaran pada satuan pendidikan dalam periode tertentu.','Jumlah Peserta Didik yang Mengikuti Proses Belajar','Kumulatif','Jumlah Peserta Didik yang Mengikuti Proses Belajar adalah jumlah peserta didik yang terdaftar sebagai peserta didik aktif pada satuan pendidikan dan mengikuti kegiatan pembelajaran sesuai kalender pendidikan pada periode pelaporan, baik melalui pembelajaran tatap muka, pembelajaran berbasis praktik, maupun bentuk pembelajaran lain yang diselenggarakan sesuai dengan ketentuan yang berlaku.Peserta didik yang dihitung adalah mereka yang memiliki status aktif dan tercatat dalam administrasi satuan pendidikan serta berpartisipasi dalam proses pembelajaran sesuai jenjang dan program pendidikan yang diikuti.','Bidang Paud Dikmas','Kepala Bidang Paud Dikmas'),
('01-01-01-03-00-01','01-01-01-03-00','01','Persentase Jumlah anak usia 7-12 tahun yang berpartisipasi dalam pendidikan dasar (APS)','Persen','','95','95.5','96','96.5','97','Persentase Jumlah Anak Usia 7–12 Tahun yang Berpartisipasi dalam Pendidikan Dasar (Angka Partisipasi Sekolah/APS) adalah persentase penduduk berusia 7–12 tahun yang sedang mengikuti pendidikan pada jenjang pendidikan dasar, baik di Sekolah Dasar (SD), Madrasah Ibtidaiyah (MI), maupun bentuk lain yang sederajat, dibandingkan dengan seluruh penduduk usia 7–12 tahun di wilayah yang sama pada tahun pengukuran.','Jumlah peserta didik jenjang SD usia 7-12 tahun dibagi jumlah penduduk usia 7-12 tahun dikali 100%','Kumulatif','Indikator ini digunakan untuk mengukur tingkat partisipasi sekolah anak usia 7–12 tahun dalam memperoleh layanan pendidikan dasar serta menjadi salah satu ukuran keberhasilan pemerintah daerah dalam meningkatkan akses pendidikan dan mendukung pelaksanaan program wajib belajar. Penduduk yang memenuhi kriteria berikut:Berusia 7–12 tahun pada tahun pengukuran.Berdomisili di wilayah kabupaten/kota.Terdaftar sebagai peserta didik aktif pada:Sekolah Dasar (SD);Madrasah Ibtidaiyah (MI);Satuan pendidikan lain yang sederajat dan diakui pemerintah.','Dapodik','Bidang Sekolah Dasar'),
('01-01-01-03-00-02','01-01-01-03-00','02','Angka Literasi SD','Persen','','72.77','75.27','77.77','80.27','82.77','Persentase peserta didik berdasarkan kemampuan dalam memahami, menggunakan, merefleksi, dan mengevaluasi beragam jenis teks (teks informasional dan teks fiksi) untuk jenjang SD.','Persentase pelaksanaan kegiatan yang mendukung capain literasi assesment sumatif akhir semester gasal dan genap dan Assesment Nasional','Kumulatif','untuk pelaksanaan kegiatan yang mendukung capain literasi assesment sumatif akhir semester gasal dan genap dan Assesment Nasional, Test Kemampuan Akademik (TKA) Bahasa Indonesia','Rapor Pendidikan','Bidang Sekolah Dasar'),
('01-01-01-03-00-03','01-01-01-03-00','03','Numerasi SD','Persen','','62.21','65.11','68.01','70.91','73.81','Persentase peserta didik berdasarkan kemampuan dalam berpikir menggunakan konsep, prosedur, fakta, dan alat matematika untuk menyelesaikan masalah sehari-hari pada berbagai jenis konteks yang relevan (jenjang SD).','Persentase pelaksanaan kegiatan yang mendukung capain Numerasi assesment sumatif akhir semester gasal dan genap dan Assesment Nasional','Kumulatif','untuk pelaksanaan kegiatan yang mendukung capain Numerasi assesment sumatif akhir semester gasal dan genap dan Assesment Nasional, TKA (test Kemampuan Akademik) mata pelajaran Matematika','Rapor Pendidikan','Bidang Sekolah Dasar'),
('01-01-01-03-01-01','01-01-01-03-01','01','Jumlah Perpustakaan Sekolah yang Telah dibangun','Ruang','5','6','8','10','12','14','Indikator ini digunakan untuk mengukur capaian pembangunan infrastruktur perpustakaan dalam rangka meningkatkan mutu layanan pendidikan, budaya literasi, dan pemenuhan Standar Nasional Pendidikan (SNP), khususnya standar sarana dan prasarana.','jumlah perpustakaan sekolah yang dibangun','Kumulatif','Jumlah Perpustakaan Sekolah yang Telah Dibangun adalah jumlah ruang atau gedung perpustakaan pada satuan pendidikan yang telah selesai dibangun sebagai bangunan baru, telah memenuhi spesifikasi teknis sesuai ketentuan yang berlaku, telah diserahterimakan, dan siap digunakan untuk mendukung layanan perpustakaan sekolah pada periode pelaporan.Pembangunan perpustakaan sekolah merupakan penyediaan fasilitas fisik berupa ruang atau gedung yang berfungsi sebagai pusat sumber belajar, tempat penyimpanan dan pemanfaatan koleksi bahan pustaka, serta sarana pendukung kegiatan literasi dan pembelajaran di satuan pendidikan.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-02-01','01-01-01-03-02','01','Jumlah Sarana, Prasarana dan Utilitas Sekolahnyang telah dibangun','Ruang','19','300','350','400','450','500','Indikator ini digunakan untuk mengukur capaian pembangunan infrastruktur pendidikan dalam rangka meningkatkan akses, mutu layanan, keselamatan, kenyamanan, dan pemenuhan standar sarana dan prasarana pendidikan.','Jumlah Sarana, Prasarana dan Utilitas Sekolah yang dibangun','Kumulatif','Jumlah Sarana, Prasarana, dan Utilitas Sekolah yang Telah Dibangun adalah jumlah unit sarana, prasarana, dan utilitas pada satuan pendidikan yang telah selesai dibangun sebagai fasilitas baru, memenuhi spesifikasi teknis sesuai ketentuan yang berlaku, telah diserahterimakan kepada satuan pendidikan, dan siap digunakan untuk mendukung penyelenggaraan proses pembelajaran pada periode pelaporan.Pembangunan meliputi pembangunan baru (new construction) yang bertujuan menambah kapasitas atau menyediakan fasilitas pendidikan yang sebelumnya belum tersedia, bukan rehabilitasi, renovasi, atau pemeliharaan bangunan yang sudah ada.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-03-01','01-01-01-03-03','01','Jumlah Perpustakaan Sekolah yang Telah direhabilitasi sedang/berat','Ruang','9','41','45','47','50','55','Indikator ini digunakan untuk mengukur capaian program rehabilitasi perpustakaan sekolah dalam rangka meningkatkan kualitas sarana pendidikan dan mendukung budaya literasi di satuan pendidikan.','Jumlah Rehabilitasi Sedang/Berat Perpustakaan Sekolah','Kumulatif','Jumlah Perpustakaan Sekolah yang Telah Direhabilitasi Sedang/Berat adalah jumlah ruang atau gedung perpustakaan pada satuan pendidikan yang telah selesai direhabilitasi dengan tingkat kerusakan sedang atau berat sehingga kembali memenuhi standar kelayakan fungsi, keamanan, kenyamanan, dan mendukung layanan perpustakaan sekolah sesuai dengan ketentuan yang berlaku pada periode pelaporan.Rehabilitasi sedang/berat merupakan pekerjaan perbaikan terhadap komponen bangunan perpustakaan yang mengalami kerusakan, tanpa mengubah fungsi utama bangunan, sehingga perpustakaan dapat kembali digunakan secara optimal sebagai pusat sumber belajar dan kegiatan literasi.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-04-01','01-01-01-03-04','01','Jumlah Mebel sekolah yang Tersedia','Paket','257','20','25','30','35','40','Indikator ini digunakan untuk mengukur ketersediaan mebel sekolah sebagai salah satu komponen penting dalam mendukung mutu layanan pendidikan.','Jumlah Mebel Sekolah yang tersedia','Kumulatif','Jumlah Mebel Sekolah yang Tersedia adalah jumlah unit mebel atau perabot sekolah yang tersedia, berada dalam kondisi baik atau layak digunakan, serta digunakan untuk mendukung penyelenggaraan proses pembelajaran, administrasi, dan layanan pendidikan pada satuan pendidikan selama periode pelaporan.Mebel sekolah merupakan bagian dari sarana pendidikan yang berfungsi sebagai perlengkapan tetap untuk menunjang kegiatan belajar mengajar, administrasi sekolah, dan aktivitas pendukung lainnya sesuai dengan standar sarana dan prasarana pendidikan.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-05-01','01-01-01-03-05','01','Jumlah Perlengkapan Sekolah yang Tersedia','Paket','2','3','5','7','10','15','Untuk mengetahui Jumlah Perlengkapan Sekolah yang Tersedia','Jumlah Perlengkapan Sekolah yang Tersedia','Kumulatif','Jumlah Perlengkapan Sekolah yang Tersedia adalah jumlah seluruh perlengkapan penunjang penyelenggaraan pendidikan yang tersedia pada satuan pendidikan, berada dalam kondisi baik atau layak digunakan, serta digunakan untuk mendukung proses pembelajaran, administrasi sekolah, layanan peserta didik, dan operasional satuan pendidikan pada periode pelaporan.Perlengkapan sekolah merupakan barang atau peralatan pendukung yang melengkapi sarana dan prasarana pendidikan, selain mebel dan bangunan, yang diperlukan agar kegiatan belajar mengajar dan pengelolaan sekolah dapat berlangsung secara efektif, efisien, aman, dan nyaman.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-03-06-01','01-01-01-03-06','01','Jumlah Siswa yang mengikuti Ajang Kompetisi/Lomba Akademik dan Non Akademik','Siswa','3647','3650','3655','3660','3665','3670','Untuk mengetahui Jumlah Siswa yang Mengikuti Ajang Kompetisi/Lomba Akademik dan Non Akademik','Jumlah Siswa yang Mengikuti Ajang Kompetisi/Lomba Akademik dan Non Akademik','Kumulatif','Pembinaan Minat, Bakat, dan Kreativitas Siswa adalah serangkaian kegiatan yang diselenggarakan oleh Dinas Pendidikan dan/atau satuan pendidikan untuk mengembangkan potensi peserta didik sesuai dengan minat, bakat, kemampuan, dan kreativitasnya melalui pembinaan, pelatihan, pendampingan, pembimbingan, seleksi, kompetisi, serta kegiatan pengembangan diri lainnya selama periode pelaporan.Kegiatan pembinaan bertujuan memberikan kesempatan kepada peserta didik untuk mengembangkan kemampuan akademik maupun nonakademik secara optimal, sehingga mampu meningkatkan prestasi, karakter, keterampilan, serta daya saing peserta didik di tingkat daerah, provinsi, nasional, maupun internasional.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-03-07-01','01-01-01-03-07','01','Jumlah pembinaan kelembagaan dan manajemen sekolah','Dokumen','36','100','150','200','250','300','Untuk mengetahui jumlah sekolah yang dilaksanakan pembinaan','Jumlah sekolah yang dilaksanakan pembinaan','Kumulatif','terselenggaranya kegiatan tujuh kebiasaan anak indonesia hebat dan coding artificial. setiap korwil mengirimkan 5 peserta terdiri dari unsur guru, kepala sekolah, pengawas. Jumlah Pembinaan Kelembagaan dan Manajemen Sekolah adalah jumlah kegiatan pembinaan yang diselenggarakan oleh Dinas Pendidikan atau instansi yang berwenang kepada satuan pendidikan dalam rangka meningkatkan kapasitas kelembagaan, tata kelola, administrasi, kepemimpinan, serta manajemen penyelenggaraan pendidikan sesuai dengan ketentuan peraturan perundang-undangan selama periode pelaporan.Pembinaan kelembagaan dan manajemen sekolah merupakan serangkaian kegiatan yang bertujuan memperkuat kemampuan sekolah dalam mengelola seluruh aspek penyelenggaraan pendidikan secara efektif, efisien, transparan, akuntabel, dan berorientasi pada peningkatan mutu layanan pendidikan.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-08-01','01-01-01-03-08','01','Jumlah Sekolah Dasar yang Mengelola Dana BOS','Satuan Pendidikan','616','616','616','616','616','616','Indikator ini digunakan untuk mengukur cakupan sekolah dasar yang telah melaksanakan pengelolaan Dana BOS secara tertib, transparan, efektif, efisien, dan akuntabel guna mendukung penyelenggaraan layanan pendidikan.','Jumlah Sekolah Dasar yang Mengelola Dana','Kumulatif','jumlah sekolah yang menerima dana BOS. Dana bos yang disalurkan setiap sekolah berdasarkan jumlah siswa. Besaran per siswa Rp. 900. 000 per siswa per tahun. Jumlah Sekolah Dasar yang Mengelola Dana Bantuan Operasional Sekolah (BOS) adalah jumlah Sekolah Dasar (SD), baik negeri maupun swasta yang menjadi kewenangan pemerintah daerah, yang menerima Dana BOS dan melaksanakan pengelolaan dana tersebut sesuai dengan ketentuan peraturan perundang-undangan pada periode pelaporan.Pengelolaan Dana BOS mencakup seluruh tahapan pengelolaan keuangan, yaitu perencanaan, pelaksanaan penggunaan dana, penatausahaan, pelaporan, dan pertanggungjawaban, sesuai dengan petunjuk teknis Dana BOS yang berlaku.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-09-01','01-01-01-03-09','01','Jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang Pendidikan yang dilaksanakan','Dokumen','1','3','3','3','3','3','Untuk mengetahui jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang pendidikan','Jumlah kegiatan sosialisasi dan advokasi kebijakan dibidang pendidikan','Kumulatif','Jumlah Kegiatan Sosialisasi dan Advokasi Kebijakan di Bidang Pendidikan yang Dilaksanakan adalah jumlah kegiatan yang telah diselenggarakan oleh Dinas Pendidikan atau instansi yang berwenang dalam rangka menyampaikan, menjelaskan, mempromosikan, mengoordinasikan, dan mengadvokasi kebijakan, program, atau regulasi di bidang pendidikan kepada pemangku kepentingan (stakeholders) selama periode pelaporan.Kegiatan sosialisasi bertujuan meningkatkan pemahaman para pemangku kepentingan terhadap kebijakan pendidikan, sedangkan advokasi bertujuan memperoleh dukungan, komitmen, serta partisipasi aktif dalam pelaksanaan kebijakan dan program pendidikan. Indikator ini mengukur jumlah kegiatan yang telah dilaksanakan, bukan jumlah peserta yang mengikuti kegiatan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-03-10-01','01-01-01-03-10','01','Jumlah Ruang Kelas Baru yang Bertambah','Ruang','1','10','15','20','25','30','Untuk mengetahui Jumlah Ruang Kelas Baru yang Bertambah','Jumlah Ruang Kelas Baru yang Bertambah','Kumulatif','jumlah raung kelas baru yang bertambah dengan rincian minimal 1 sekolah 2 ruang . Pembangunan Ruang Kelas Baru adalah kegiatan pembangunan fisik ruang kelas yang baru pada satuan pendidikan yang menjadi kewenangan pemerintah daerah untuk menambah kapasitas layanan pendidikan. Pembangunan dilakukan sesuai dengan standar teknis bangunan gedung dan standar sarana dan prasarana pendidikan, telah selesai dilaksanakan, diserahterimakan, dan siap digunakan untuk kegiatan pembelajaran pada periode pelaporan.Pembangunan ruang kelas baru bertujuan memenuhi kebutuhan ruang belajar akibat pertambahan jumlah peserta didik, pembukaan rombongan belajar baru, penggantian ruang kelas darurat, atau pemenuhan standar sarana pendidikan. Indikator ini mengukur jumlah ruang kelas baru yang berhasil dibangun, bukan jumlah sekolah yang menerima pembangunan.','Bidang PTK','Kepala Bidang PTK'),
('01-01-01-03-11-01','01-01-01-03-11','01','Jumlah Sarana, Prasarana dan Utilitas Sekolah yang Telah Direhabilitasi','Unit','4','5','6','7','8','9','untuk mengetahui Rehabilitasi Sedang/Berat Sarana, Prasarana dan Utilitas Sekolah','jumlah Rehabilitasi Sedang/Berat Sarana, Prasarana dan Utilitas Sekolah','Kumulatif','Digunakan untuk merehabilitasi sedang berat sarana prasrana dan utilitas sekolah yang direhab berupa : ruang bermain, ruang gedung, ruang guru, ruang ibadah, ruang kelas, ruang kepala sekolah, ruang lab tk, ruang lab ipa, ruag perpustakaan, ruang sirkulasi, ruang toilet, ruang uks, rumah dinas, , bangunan pagar keliling, bangunan paving, sarana air bersih, bangunan talud.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-03-12-01','01-01-01-03-12','01','Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Orang','100','100','100','100','100','100','Kegiatan ini dapat ditujukan kepada pendidik, tenaga kependidikan, pengawas sekolah, penilik, pengelola satuan pendidikan, maupun pihak lain yang terlibat dalam penyelenggaraan pendidikan. Indikator ini mengukur jumlah kegiatan yang telah dilaksanakan','Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Kumulatif','Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan adalah kegiatan pengembangan kompetensi yang diselenggarakan oleh Dinas Pendidikan atau instansi yang berwenang dalam bentuk bimbingan teknis (bimtek), pelatihan, magang, dan/atau praktik kerja lapangan (PKL) guna meningkatkan pengetahuan, keterampilan, sikap profesional, dan kapasitas sumber daya manusia di bidang pendidikan sesuai dengan tugas, fungsi, dan kebutuhan penyelenggaraan layanan pendidikan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-03-13-01','01-01-01-03-13','01','Jumlah Satuan Pendidikan yang Menyelenggarakan Proses Belajar','Peserta Didik','616','616','616','616','616','616','Untuk mengetahui Jumlah Satuan Pendidikan yang Menyelenggarakan Proses Belajar','Jumlah Satuan Pendidikan yang Menyelenggarakan Proses Belajar','Kumulatif','Untuk kegiatan assesment sumatif akhir semester, akhir jenjang dan assesment nasional, untuk Kegiatan Test Kemampuan Akademik (TKA) untuk kelas 6 mulai tahun 2026 untuk siswa. Siswa yang mengikuti TKA mendapatkan Sertifikat sebagai syarat untuk melanjutkan ke jenjang selanjutnya. Program ini diluncurkan oleh Kementrian pendidikan Dasar dan Menengah','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-14-01','01-01-01-03-14','01','Jumlah Ruang Kelas Sekolah yang Telah Direhabilitasi sedang/berat','Unit','31','13','17','19','23','25','Indikator ini mengukur jumlah ruang kelas yang telah selesai direhabilitasi dan siap dimanfaatkan kembali untuk kegiatan belajar mengajar.','Jumlah Ruang Kelas Sekolah yang telah Direhabilitasi Sedang/Berat','Kumulatif','Jumlah Ruang Kelas Sekolah yang Telah Direhabilitasi Sedang/Berat adalah jumlah ruang kelas pada satuan pendidikan yang menjadi kewenangan pemerintah daerah yang telah selesai dilakukan rehabilitasi dengan tingkat kerusakan sedang atau berat sesuai hasil penilaian kondisi bangunan, sehingga ruang kelas kembali memenuhi standar kelayakan fungsi, keamanan, keselamatan, kesehatan, dan kenyamanan untuk digunakan sebagai tempat proses pembelajaran pada periode pelaporan.Rehabilitasi sedang/berat merupakan pekerjaan perbaikan terhadap komponen bangunan yang mengalami kerusakan sedang atau berat tanpa mengubah fungsi utama bangunan. Pekerjaan rehabilitasi dilakukan berdasarkan hasil identifikasi tingkat kerusakan dan dilaksanakan sesuai dengan spesifikasi teknis serta standar konstruksi bangunan gedung pendidikan yang berlaku.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-03-15-01','01-01-01-03-15','01','Jumlah Peserta Didik Sekolah Dasar yang Menerima Biaya Personil Peserta Didik','Peserta Didik','175','11400','11400','11400','11400','11400','Untuk mengetahui Jumlah Peserta Didik Sekolah Dasar yang Menerima Biaya Personil Peserta Didik','Jumlah Peserta Didik Sekolah Dasar yang Menerima Biaya Personil Peserta Didik','Kumulatif','Jumlah Peserta didik yang menerima BSM. Jumlah Peserta Didik Sekolah Dasar yang Menerima Biaya Personil Peserta Didik adalah jumlah peserta didik aktif pada jenjang Sekolah Dasar (SD), baik negeri maupun swasta sesuai kewenangan pemerintah daerah, yang menerima bantuan biaya personal untuk mendukung kebutuhan pendidikan individu selama periode pelaporan sesuai dengan ketentuan peraturan perundang-undangan.Biaya Personil Peserta Didik adalah bantuan yang diberikan secara langsung atau tidak langsung kepada peserta didik untuk memenuhi kebutuhan pribadi yang diperlukan agar dapat mengikuti proses pembelajaran secara berkelanjutan. Bantuan ini bertujuan mengurangi hambatan ekonomi, meningkatkan akses pendidikan, mencegah putus sekolah, serta mendukung pemerataan layanan pendidikan.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-16-01','01-01-01-03-16','01','Jumlah Alat Praktik dan Peraga Siswa yang Tersedia','Paket','73','10','15','20','25','30','Untuk mengetahui Jumlah Alat Praktik dan Peraga Siswa yang tersedia','Jumlah Alat Praktik dan Peraga Siswa yangTersedia','Kumulatif','Pengadaan Alat Praktik dan Peraga Siswa adalah kegiatan penyediaan alat praktik dan alat peraga pembelajaran melalui proses pengadaan yang dilaksanakan oleh pemerintah daerah atau satuan pendidikan sesuai dengan ketentuan peraturan perundang-undangan, untuk memenuhi kebutuhan sarana pembelajaran peserta didik dalam rangka mendukung proses pembelajaran yang efektif, interaktif, kontekstual, dan berbasis praktik.Alat praktik merupakan peralatan yang digunakan oleh peserta didik untuk melakukan kegiatan praktikum, percobaan, simulasi, atau latihan keterampilan. Alat peraga merupakan media pembelajaran yang digunakan untuk membantu guru menjelaskan konsep, prinsip, atau materi pembelajaran sehingga lebih mudah dipahami oleh peserta didik.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-03-17-01','01-01-01-03-17','01','Jumlah Dokumen Hasil Koordinasi, Perencanaan, Supervisi dan Evaluasi Layanan di Bidang Pendidikan','Dokumen',' NA','7','7','7','7','7','Untuk mengetahui Jumlah Jumlah Dokumen Hasil Koordinasi, Perencanaan, Supervisi dan Evaluasi Layanan di Bidang Pendidikan','Jumlah Tenaga Pengelola yang Meningkat Kapasitasnya dalam Pengelolaan Dana BOS Sekolah Dasar','Kumulatif','Jumlah Dokumen Hasil Koordinasi, Perencanaan, Supervisi, dan Evaluasi Layanan di Bidang Pendidikan adalah jumlah dokumen resmi yang dihasilkan dari pelaksanaan kegiatan koordinasi, perencanaan, supervisi, monitoring, evaluasi, dan pengendalian penyelenggaraan layanan pendidikan yang disusun oleh Dinas Pendidikan atau unit kerja terkait selama periode pelaporan.Dokumen tersebut merupakan keluaran (output) administrasi yang memuat hasil pelaksanaan kegiatan, analisis, rekomendasi, rencana tindak lanjut, atau informasi strategis yang digunakan sebagai dasar pengambilan keputusan, penyusunan kebijakan, peningkatan mutu layanan, serta perencanaan program pendidikan.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-03-18-01','01-01-01-03-18','01','Jumlah Ruang Guru/Kepala Sekolah/TU yang Telah Direhabilitasi Sedang/Berat','Ruang','2','8','10','12','14','16','Untuk mengetahui Ruang Guru/Kepala Sekolah/TU yang Terehabilitasi Sedang/Berat','Jumlah Ruang Guru/Kepala Sekolah/TU yang Telah Direhabilitasi Sedang/Berat','Kumulatif','Jumlah Ruang Guru/Kepala Sekolah/Tata Usaha yang Telah Direhabilitasi Sedang/Berat adalah jumlah ruang guru, ruang kepala sekolah, dan/atau ruang tata usaha pada satuan pendidikan yang telah selesai direhabilitasi dengan tingkat kerusakan sedang atau berat sehingga kembali memenuhi standar kelayakan fungsi, keamanan, kenyamanan, dan mendukung penyelenggaraan administrasi serta manajemen sekolah sesuai dengan ketentuan yang berlaku pada periode pelaporan.Rehabilitasi sedang/berat merupakan kegiatan perbaikan terhadap sebagian atau sebagian besar komponen bangunan yang mengalami kerusakan, tanpa mengubah fungsi utama ruang, sehingga ruang dapat digunakan kembali secara optimal.','Bidang Sekolah Dasar','Kepala Bidang Sekolah Dasar'),
('01-01-01-04-00-01','01-01-01-04-00','01','Persentase Jumlah anak usia 13-15 tahun yang berpartisipasi dalam pendidikan dasar (APS)','Persen','','99.18','99.61','100','100','100','Indikator ini digunakan untuk mengukur tingkat partisipasi anak usia 13–15 tahun dalam memperoleh layanan pendidikan dasar sebagai bagian dari pelaksanaan program wajib belajar dan upaya pemerintah daerah dalam meningkatkan akses pendidikan yang merata, berkualitas, dan inklusif.','Jumlah peserta didik jenjang SMP usia 13-15 tahun dibagi jumlah penduduk usia 13-15 tahun dikali 100%','Kumulatif','Persentase Jumlah Anak Usia 13–15 Tahun yang Berpartisipasi dalam Pendidikan Dasar (APS) adalah persentase penduduk berusia 13–15 tahun yang sedang mengikuti pendidikan pada jenjang pendidikan dasar, yaitu Sekolah Menengah Pertama (SMP), Madrasah Tsanawiyah (MTs), atau satuan pendidikan sederajat, dibandingkan dengan jumlah seluruh penduduk usia 13–15 tahun di wilayah yang sama pada tahun pengukuran.. Indikator ini bertujuan untuk:Mengukur tingkat partisipasi sekolah penduduk usia 13–15 tahun pada jenjang pendidikan dasar.Menilai keberhasilan pemerintah daerah dalam memperluas akses pendidikan jenjang SMP/sederajat.Mengidentifikasi jumlah anak usia sekolah yang belum memperoleh layanan pendidikan dasar.Menjadi dasar penyusunan kebijakan penanganan Anak Tidak Sekolah (ATS), pencegahan putus sekolah, dan peningkatan akses pendidikan.','Dapodik','Bidang Sekolah Menengah'),
('01-01-01-04-00-02','01-01-01-04-00','02','Angka Literasi SMP','Persen','','80.9','82','83.1','84.2','85.3','Persentase peserta didik berdasarkan kemampuan dalam memahami, menggunakan, merefleksi, dan mengevaluasi beragam jenis teks (teks informasional dan teks fiksi) untuk jenjang SMP Indikator ini digunakan untuk mengukur kualitas hasil belajar peserta didik SMP pada aspek literasi sebagai salah satu kompetensi dasar yang mendukung peningkatan mutu pendidikan.','angka literasi smp diperoleh dari Rapor Pendidikan yang diterbitkan oleh Kementerian Pendidikan Dasar dan Menengah berdasarkan hasil Asesmen Nasional (AN).','Kumulatif','Angka Literasi SMP adalah tingkat capaian kemampuan literasi peserta didik jenjang Sekolah Menengah Pertama (SMP) dalam memahami, menggunakan, mengevaluasi, merefleksikan, dan menginterpretasikan berbagai jenis teks untuk menyelesaikan masalah, mengembangkan pengetahuan, serta berpartisipasi secara efektif dalam kehidupan bermasyarakat, yang diukur melalui hasil asesmen literasi sesuai instrumen yang ditetapkan oleh pemerintah.','Rapor Pendidikan',''),
('01-01-01-04-00-03','01-01-01-04-00','03','Numerasi SMP','Persen','','70.3','71.8','73.3','74.8','76.3','Persentase peserta didik berdasarkan kemampuan dalam berpikir menggunakan konsep, prosedur, fakta, dan alat matematika untuk menyelesaikan masalah sehari-hari pada berbagai jenis konteks yang relevan (jenjang SMP).','angka numerasi smp diperoleh dari Rapor Pendidikan yang diterbitkan oleh Kementerian Pendidikan Dasar dan Menengah berdasarkan hasil Asesmen Nasional (AN).','Kumulatif','Angka Numerasi SMP adalah tingkat capaian kemampuan numerasi peserta didik jenjang Sekolah Menengah Pertama (SMP) dalam menggunakan konsep, prosedur, fakta, dan alat matematika untuk menyelesaikan masalah dalam berbagai konteks kehidupan sehari-hari, yang diukur berdasarkan hasil Asesmen Nasional (AN) dan disajikan dalam Rapor Pendidikan.Kemampuan numerasi mencakup kemampuan peserta didik untuk:- memahami dan menggunakan bilangan serta operasi hitung;- mengenali pola dan hubungan matematis;- menginterpretasikan data, tabel, grafik, dan diagram;- mengukur serta memahami konsep geometri;- menerapkan penalaran matematis untuk memecahkan masalah kontekstual.','data Rapor Pendidikan','Bidang Sekolah Menengah'),
('01-01-01-04-01-01','01-01-01-04-01','01','Jumlah Ruang Laboratorium yang Telah dibangun','Ruang','2','2','4','6','8','10','Indikator ini digunakan untuk mengukur capaian pembangunan sarana laboratorium dalam rangka meningkatkan mutu pembelajaran, terutama pembelajaran berbasis praktik, eksperimen, dan pengembangan keterampilan peserta didik.','Jumlah Ruang Laboratorium yang Telah Dibangun','Kumulatif','Jumlah Ruang Laboratorium yang Telah Dibangun adalah jumlah ruang laboratorium baru pada satuan pendidikan yang telah selesai dibangun, memenuhi spesifikasi teknis dan standar sarana prasarana pendidikan, telah diserahterimakan kepada satuan pendidikan, serta siap digunakan untuk kegiatan praktikum, eksperimen, penelitian sederhana, dan pembelajaran berbasis praktik pada periode pelaporan.Pembangunan ruang laboratorium merupakan pembangunan fisik baru yang bertujuan menambah kapasitas dan ketersediaan fasilitas laboratorium di sekolah, bukan rehabilitasi, renovasi, atau pemeliharaan ruang laboratorium yang sudah ada.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-02-01','01-01-01-04-02','01','Jumlah Sarana, Prasarana dan Utilitas Sekolah yang telah dibangun','Unit','6','9','15','17','19','23','Untuk mengetahui Jumlah Sarana, Prasarana dan Utilitas Sekolah yang Telah Dibangun','Indikator ini digunakan untuk mengukur capaian pembangunan infrastruktur pendidikan sebagai bagian dari upaya peningkatan akses, mutu, pemerataan, keamanan, dan kenyamanan layanan pendidikan.','Kumulatif','Pembangunan Sarana, Prasarana, dan Utilitas Sekolah adalah kegiatan pembangunan fisik berupa penyediaan sarana, prasarana, dan utilitas baru pada satuan pendidikan yang menjadi kewenangan pemerintah daerah, yang telah selesai dilaksanakan sesuai spesifikasi teknis, memenuhi standar sarana dan prasarana pendidikan, telah diserahterimakan, dan siap digunakan untuk mendukung penyelenggaraan proses pembelajaran serta layanan pendidikan pada periode pelaporan.Pembangunan dimaksud merupakan pembangunan baru (new construction) yang bertujuan menambah kapasitas, meningkatkan kualitas layanan pendidikan, serta memenuhi kebutuhan fasilitas sekolah. Indikator ini tidak mencakup kegiatan rehabilitasi, renovasi, atau pemeliharaan bangunan dan fasilitas yang telah ada.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-03-01','01-01-01-04-03','01','Jumlah Ruang kelas sekolah yang Telah Direhabilitasi Sedang/Berat','Unit','31','13','17','19','23','25','Indikator ini mengukur jumlah ruang kelas yang telah selesai direhabilitasi dan siap dimanfaatkan kembali untuk kegiatan belajar mengajar.','Jumlah Ruang Kelas Sekolah yang telah Direhabilitasi Sedang/Berat','Kumulatif','Jumlah Ruang Kelas Sekolah yang Telah Direhabilitasi Sedang/Berat adalah jumlah ruang kelas pada satuan pendidikan yang menjadi kewenangan pemerintah daerah yang telah selesai dilakukan rehabilitasi dengan tingkat kerusakan sedang atau berat sesuai hasil penilaian kondisi bangunan, sehingga ruang kelas kembali memenuhi standar kelayakan fungsi, keamanan, keselamatan, kesehatan, dan kenyamanan untuk digunakan sebagai tempat proses pembelajaran pada periode pelaporan.Rehabilitasi sedang/berat merupakan pekerjaan perbaikan terhadap komponen bangunan yang mengalami kerusakan sedang atau berat tanpa mengubah fungsi utama bangunan. Pekerjaan rehabilitasi dilakukan berdasarkan hasil identifikasi tingkat kerusakan dan dilaksanakan sesuai dengan spesifikasi teknis serta standar konstruksi bangunan gedung pendidikan yang berlaku.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-04-01','01-01-01-04-04','01','Jumlah Sarana, Prasarana dan Utilitas Sekolah yang Telah Direhabilitasi','Unit','4','5','6','7','8','9','untuk mengetahui Rehabilitasi Sedang/Berat Sarana, Prasarana dan Utilitas Sekolah','jumlah Rehabilitasi Sedang/Berat Sarana, Prasarana dan Utilitas Sekolah','Kumulatif','Digunakan untuk merehabilitasi sedang berat sarana prasrana dan utilitas sekolah yang direhab berupa : ruang bermain, ruang gedung, ruang guru, ruang ibadah, ruang kelas, ruang kepala sekolah, ruang lab tk, ruang lab ipa, ruag perpustakaan, ruang sirkulasi, ruang toilet, ruang uks, rumah dinas, , bangunan pagar keliling, bangunan paving, sarana air bersih, bangunan talud.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-05-01','01-01-01-04-05','01','Jumlah mebel yang ada pada satuan pendidikan','Paket','194','20','25','30','35','40','Indikator ini mengukur jumlah unit mebel yang tersedia, baik yang berasal dari pengadaan pemerintah, bantuan, hibah, maupun sumber pendanaan lain yang sah, dan telah tercatat dalam inventaris satuan pendidikan.','Jumlah mebel yang ada pada satuan pendidikan','Kumulatif','Definisi OperasionalJumlah Mebel yang Ada pada Satuan Pendidikan adalah jumlah seluruh mebel atau perabot pendidikan yang tersedia pada satuan pendidikan, berada dalam kondisi baik atau layak digunakan, serta digunakan untuk mendukung proses pembelajaran, administrasi, dan penyelenggaraan layanan pendidikan pada periode pelaporan.Mebel merupakan perlengkapan yang berfungsi sebagai sarana pendukung kegiatan belajar mengajar maupun administrasi sekolah dan menjadi bagian dari standar sarana pendidikan sesuai dengan ketentuan peraturan perundang-undangan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-06-01','01-01-01-04-06','01','Jumlah Perlengkapan Sekolah yang Tersedia','Paket','2','3','5','7','10','15','Untuk mengetahui Jumlah Perlengkapan Sekolah yang Tersedia','Jumlah Perlengkapan Sekolah yang Tersedia','Kumulatif','Jumlah Perlengkapan Sekolah yang Tersedia adalah jumlah seluruh perlengkapan penunjang penyelenggaraan pendidikan yang tersedia pada satuan pendidikan, berada dalam kondisi baik atau layak digunakan, serta digunakan untuk mendukung proses pembelajaran, administrasi sekolah, layanan peserta didik, dan operasional satuan pendidikan pada periode pelaporan.Perlengkapan sekolah merupakan barang atau peralatan pendukung yang melengkapi sarana dan prasarana pendidikan, selain mebel dan bangunan, yang diperlukan agar kegiatan belajar mengajar dan pengelolaan sekolah dapat berlangsung secara efektif, efisien, aman, dan nyaman.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-07-01','01-01-01-04-07','01','Jumlah Peserta didik Sekolah Menengah Pertama yang Menerima Biaya Personil Peserta Didik','peserta didik','11300','11400','11400','11400','11400','11400','Untuk menge tahui Jumlah Peserta didik Sekolah Menengah Pertama yang Menerima Biaya Personil Peserta Didik','Jumlah Peserta didik Sekolah MenengPertama yang Menerima Biaya Personil Peserta Didikah','Kumulatif','Jumlah Peserta Didik Sekolah Menengah Pertama (SMP) yang Menerima Biaya Personil Peserta Didik adalah jumlah peserta didik aktif pada jenjang SMP, baik negeri maupun swasta sesuai kewenangan pemerintah daerah, yang menerima bantuan biaya personal untuk memenuhi kebutuhan individu dalam menunjang proses pendidikan selama periode pelaporan, sesuai dengan ketentuan peraturan perundang-undangan dan petunjuk teknis program yang berlaku.Biaya Personil Peserta Didik merupakan bantuan yang diberikan kepada peserta didik untuk membantu memenuhi kebutuhan pribadi yang berkaitan dengan pendidikan sehingga peserta didik dapat mengikuti proses pembelajaran secara berkelanjutan. Bantuan ini bertujuan untuk mengurangi hambatan ekonomi, meningkatkan akses pendidikan, mencegah putus sekolah, dan mendukung pemerataan layanan pendidikan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-08-01','01-01-01-04-08','01','Jumlah Siswa yang mengikuti Ajang Kompetisi/Lomba Akademik dan Non Akademik','Siswa','3647','3650','3655','3660','3665','3670','Untuk mengetahui Jumlah Siswa yang Mengikuti Ajang Kompetisi/Lomba Akademik dan Non Akademik','Jumlah Siswa yang Mengikuti Ajang Kompetisi/Lomba Akademik dan Non Akademik','Kumulatif','Pembinaan Minat, Bakat, dan Kreativitas Siswa adalah serangkaian kegiatan yang diselenggarakan oleh Dinas Pendidikan dan/atau satuan pendidikan untuk mengembangkan potensi peserta didik sesuai dengan minat, bakat, kemampuan, dan kreativitasnya melalui pembinaan, pelatihan, pendampingan, pembimbingan, seleksi, kompetisi, serta kegiatan pengembangan diri lainnya selama periode pelaporan.Kegiatan pembinaan bertujuan memberikan kesempatan kepada peserta didik untuk mengembangkan kemampuan akademik maupun nonakademik secara optimal, sehingga mampu meningkatkan prestasi, karakter, keterampilan, serta daya saing peserta didik di tingkat daerah, provinsi, nasional, maupun internasional.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-09-01','01-01-01-04-09','01','Terlaksananya Pembinaan Kelembagaan dan Manajemen','Satuan Pendidikan','65','100','100','100','100','100','Indikator ini mengukur jumlah sekolah yang dilakukan kegiatan pembinaan kelembagaan dan manajemen yang telah dilaksanakan dalam periode pelaporan','Jumlah Sekolah yang Dilaksanakan Pembinaan Kelembagaan dan manajemen','Kumulatif','Terlaksananya Pembinaan Kelembagaan dan Manajemen adalah pelaksanaan kegiatan pembinaan yang dilakukan oleh Dinas Pendidikan atau instansi yang berwenang kepada satuan pendidikan untuk meningkatkan kapasitas kelembagaan, tata kelola, administrasi, kepemimpinan, serta manajemen sekolah agar penyelenggaraan layanan pendidikan berjalan secara efektif, efisien, transparan, akuntabel, dan sesuai dengan ketentuan peraturan perundang-undangan.Pembinaan dilakukan melalui berbagai bentuk kegiatan, seperti sosialisasi, bimbingan teknis, pendampingan, supervisi, monitoring, evaluasi, konsultasi, maupun fasilitasi, yang bertujuan meningkatkan kualitas pengelolaan satuan pendidikan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-10-01','01-01-01-04-10','01','Jumlah Sekolah Menengah Pertama yang Mengelola Dana BOS','Satuan Pendidikan','100','100','100','100','100','100','Untuk mengetahui Jumlah Sekolah Menengah Pertama yang Mengelola Dana BOS','Jumlah Sekolah Menengah pertama yang Mengelola Dana','Kumulatif','jumlah sekolah yang menerima dana BOS. Dana bos yang disalurkan setiap sekolah berdasarkan jumlah siswa.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-11-01','01-01-01-04-11','01','Jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang Pendidikan yang dilaksanakan','Dokumen','1','3','3','3','3','3','Untuk mengetahui jumlah kegiatan sosialisasi dan advokasi kebijakan di bidang pendidikan','Jumlah kegiatan sosialisasi dan advokasi kebijakan dibidang pendidikan','Kumulatif','Jumlah Kegiatan Sosialisasi dan Advokasi Kebijakan di Bidang Pendidikan yang Dilaksanakan adalah jumlah kegiatan yang telah diselenggarakan oleh Dinas Pendidikan atau instansi yang berwenang dalam rangka menyampaikan, menjelaskan, mempromosikan, mengoordinasikan, dan mengadvokasi kebijakan, program, atau regulasi di bidang pendidikan kepada pemangku kepentingan (stakeholders) selama periode pelaporan.Kegiatan sosialisasi bertujuan meningkatkan pemahaman para pemangku kepentingan terhadap kebijakan pendidikan, sedangkan advokasi bertujuan memperoleh dukungan, komitmen, serta partisipasi aktif dalam pelaksanaan kebijakan dan program pendidikan. Indikator ini mengukur jumlah kegiatan yang telah dilaksanakan, bukan jumlah peserta yang mengikuti kegiatan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-12-01','01-01-01-04-12','01','Jumlah Peserta Didik yang Mengikuti Proses Belajar dan Ujian','SatuanPendidikan','100','100','100','100','100','100','Untuk mengetahui Jumlah Peserta Didik yang Mengikuti Proses belaar dan ujian','Jumlah Peserta Didik yang Mengikuti Proses','Kumulatif','Jumlah Peserta Didik yang Mengikuti Proses Belajar dan Ujian adalah jumlah peserta didik yang terdaftar aktif pada satuan pendidikan dan mengikuti kegiatan pembelajaran serta penilaian hasil belajar (ujian/asesmen) sesuai dengan kurikulum dan kalender pendidikan pada periode pelaporan.Peserta didik dinyatakan mengikuti proses belajar apabila berpartisipasi dalam kegiatan pembelajaran yang diselenggarakan oleh satuan pendidikan, baik secara tatap muka, pembelajaran daring, maupun pembelajaran bauran (blended learning), sesuai dengan ketentuan yang berlaku. Peserta didik dinyatakan mengikuti ujian apabila tercatat sebagai peserta dan mengikuti asesmen atau ujian yang diselenggarakan oleh satuan pendidikan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-13-01','01-01-01-04-13','01','Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Orang','100','100','100','100','100','100','Kegiatan ini dapat ditujukan kepada pendidik, tenaga kependidikan, pengawas sekolah, penilik, pengelola satuan pendidikan, maupun pihak lain yang terlibat dalam penyelenggaraan pendidikan. Indikator ini mengukur jumlah kegiatan yang telah dilaksanakan','Jumlah Peserta Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan yang dilaksanakan','Kumulatif','Bimbingan Teknis, Pelatihan, dan/atau Magang/PKL untuk Peningkatan Kapasitas Bidang Pendidikan adalah kegiatan pengembangan kompetensi yang diselenggarakan oleh Dinas Pendidikan atau instansi yang berwenang dalam bentuk bimbingan teknis (bimtek), pelatihan, magang, dan/atau praktik kerja lapangan (PKL) guna meningkatkan pengetahuan, keterampilan, sikap profesional, dan kapasitas sumber daya manusia di bidang pendidikan sesuai dengan tugas, fungsi, dan kebutuhan penyelenggaraan layanan pendidikan.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-14-01','01-01-01-04-14','01','Jumlah Alat Praktik dan Peraga Siswa yang Tersedia','Paket','73','10','15','20','25','30','Untuk mengetahui Jumlah Alat Praktik dan Peraga Siswa yang tersedia','Jumlah Alat Praktik dan Peraga Siswa yangTersedia','Kumulatif','Pengadaan Alat Praktik dan Peraga Siswa adalah kegiatan penyediaan alat praktik dan alat peraga pembelajaran melalui proses pengadaan yang dilaksanakan oleh pemerintah daerah atau satuan pendidikan sesuai dengan ketentuan peraturan perundang-undangan, untuk memenuhi kebutuhan sarana pembelajaran peserta didik dalam rangka mendukung proses pembelajaran yang efektif, interaktif, kontekstual, dan berbasis praktik.Alat praktik merupakan peralatan yang digunakan oleh peserta didik untuk melakukan kegiatan praktikum, percobaan, simulasi, atau latihan keterampilan. Alat peraga merupakan media pembelajaran yang digunakan untuk membantu guru menjelaskan konsep, prinsip, atau materi pembelajaran sehingga lebih mudah dipahami oleh peserta didik.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-15-01','01-01-01-04-15','01','Jumlah Ruang Unit Kesehatan Sekolah yang telah dibangun','Ruang','2','5','7','9','11','13','Untuk mengetahui Jumlah Ruang Unit Kesehatan Sekolah yang Telah Dibangun','Jumlah Ruang Unit Kesehatan Sekolah yang Telah Dibangun','Kumulatif','Pembangunan Ruang Unit Kesehatan Sekolah (UKS) adalah kegiatan pembangunan fisik ruang UKS baru pada satuan pendidikan yang menjadi kewenangan pemerintah daerah, yang telah selesai dilaksanakan sesuai dengan spesifikasi teknis, memenuhi standar sarana dan prasarana pendidikan, telah diserahterimakan, dan siap digunakan sebagai fasilitas pelayanan kesehatan dasar, pembinaan perilaku hidup bersih dan sehat (PHBS), pertolongan pertama pada peserta didik, serta pelaksanaan program Usaha Kesehatan Sekolah (UKS) pada periode pelaporan.Pembangunan ruang UKS merupakan pembangunan baru (new construction) untuk menambah ketersediaan fasilitas kesehatan di sekolah, dan tidak termasuk kegiatan rehabilitasi, renovasi, atau pemeliharaan ruang UKS yang telah ada.','Bidang Sekolah Menengah','Kepala Bidang Sekolah Menengah'),
('01-01-01-04-16-01','01-01-01-04-16','01','Jumlah Ruang Kelas Baru yang Bertambah','Ruang','1','10','15','20','25','30','Untuk mengetahui Jumlah Ruang Kelas Baru yang Bertambah','Jumlah Ruang Kelas Baru yang Bertambah','Kumulatif','jumlah raung kelas baru yang bertambah dengan rincian minimal 1 sekolah 2 ruang . Pembangunan Ruang Kelas Baru adalah kegiatan pembangunan fisik ruang kelas yang baru pada satuan pendidikan yang menjadi kewenangan pemerintah daerah untuk menambah kapasitas layanan pendidikan. Pembangunan dilakukan sesuai dengan standar teknis bangunan gedung dan standar sarana dan prasarana pendidikan, telah selesai dilaksanakan, diserahterimakan, dan siap digunakan untuk kegiatan pembelajaran pada periode pelaporan.Pembangunan ruang kelas baru bertujuan memenuhi kebutuhan ruang belajar akibat pertambahan jumlah peserta didik, pembukaan rombongan belajar baru, penggantian ruang kelas darurat, atau pemenuhan standar sarana pendidikan. Indikator ini mengukur jumlah ruang kelas baru yang berhasil dibangun, bukan jumlah sekolah yang menerima pembangunan.','Bidang PTK','Kepala Bidang PTK'),
('01-01-02-00-00-01','01-01-02-00-00','01','Prosentase guru yang sudah memiliki sertifikat pendidik','Persen','','90.2','92.7','96.2','98.7','99.5','Indikator ini menggambarkan tingkat pemenuhan guru profesional yang telah memenuhi standar kompetensi guru dan mendapatkan pengakuan resmi sebagai tenaga profesional pendidik sesuai ketentuan yang berlaku, Indikator ini dipilih untuk mengetahui persentase guru yang telah memiliki sertifikat pendidik jenjang TK, SD, SMP di sekolah negeri dan swasta yang tercatat pada Aplikasi Dapodik.','jumlah guru yang memiliki sertifikat pendidik di semua jenjang (Tk,SD,SMP) baik ASN, Non ASN di sekolah negeri dan swasta yang terdata di Dapodik Dibagi Jumlah Guru ASN dan Non ASN (Tk,SD,SMP) X 100%','Kumulatif','Sertifikat pendidik adalah bukti formal sebagai pengakuan yang diberikan kepada guru sebagai tenaga profesional setelah memenuhi persyaratan dan dinyatakan lulus dalam proses sertifikasi guru. Persentase Guru yang Sudah Memiliki Sertifikat Pendidik adalah ukuran yang menunjukkan proporsi jumlah guru yang telah memperoleh sertifikat pendidik sebagai bukti pengakuan profesionalisme guru dibandingkan dengan jumlah seluruh guru yang menjadi sasaran pengukuran dalam suatu wilayah dan periode tertentu.Indikator ini menggambarkan tingkat pemenuhan guru profesional yang telah memenuhi standar kompetensi guru dan mendapatkan pengakuan resmi sebagai tenaga profesional pendidik sesuai ketentuan yang berlaku','data Dapodik dan Aplikasi Sim Tunjangan',''),
('01-01-02-01-00-01','01-01-02-01-00','01','Jumlah guru dan tenaga kependidikan yang mengikuti pelatihan','Orang','','500','600','700','800','900','untuk mengetahui jumlah guru dan tenaga kependidikan yang mengikuti pelatihan','jumlah guru dan tenaga kependidikan yang mengikuti pelatihan','Kumulatif','jumlah guru dan tenaga kependidikan yang mengikuti pelatihan pengembangan kompetensi pendidikan tingkat kabupaten, propinsi dan nasional (Peningkatan Kompetensi Guru pada Pembelajaran, Peningkatan Kompetensi Tenaga Kependidikan, Pembuatan Media Pembelajaran Interaktif dan Digialisasi Pembelajaran)','Bidang PTK','Kepala Bidang Pendidik dan Tenaga Kependidikan'),
('01-01-02-01-00-02','01-01-02-01-00','02','persentase sekolah dengan ketercukupan guru','Persen','','12','12.5','13','13.5','14','untuk mengetahui jumlah persentase sekolah dengan ketercukupan guru untuk satuan pendidikan negeri dibawah kewenangan Pemerintah kabupaten Banjarnegara jenjang (TK, SD, SMP)','Jumlah sekolah dengan ketercukupan guru dibagi jumlah seluruh sekolah dikali 100%','Kumulatif','Persentase Sekolah dengan Ketercukupan Guru adalah persentase jumlah satuan pendidikan yang memiliki jumlah dan kualifikasi guru sesuai dengan kebutuhan pembelajaran berdasarkan ketentuan peraturan perundang-undangan dibandingkan dengan jumlah seluruh satuan pendidikan yang menjadi kewenangan pemerintah daerah pada jenjang pendidikan tertentu dalam satu tahun pelajaran atau tahun anggaran.Ketercukupan guru merupakan kondisi ketika suatu sekolah memiliki jumlah guru yang memadai untuk melaksanakan proses pembelajaran sesuai struktur kurikulum, rombongan belajar (rombel), beban kerja guru, serta mata pelajaran yang harus diajarkan. Guru yang diperhitungkan meliputi guru berstatus Aparatur Sipil Negara (ASN) maupun non-ASN yang diakui dan ditugaskan secara resmi sesuai ketentuan yang berlaku. Sesuai dengan permendikbud nomor : Peraturan Menteri Pendidikan Dasar dan Menengah Nomor 11 Tahun 2025 tentang Pemenuhan Beban Kerja Guru. untuk guru ASN dan Non ASN','Bidang PTK','Kepala Bidang Pendidik dan Tenaga Kependidikan'),
('01-01-02-01-01-01','01-01-02-01-01','01','Jumlah Dokumen Hasil Perhitungan dan Pemetaan Pendidik dan Tenaga Kependidikan Satuan Satuan Pendidikan Dasar, PAUD, dan Pendidikan Nonformal/Kesetaraan','Dokumen','1','7','7','7','7','7','Untuk mengetahui Jumlah Dokumen Hasil Perhitungan dan Pemetaan Pendidik dan Tenaga Kependidikan Satuan Satuan Pendidikan Dasar, PAUD, dan PendidikanNon ormal/Kesetaraan','Jumlah Dokumen Hasil Perhitungan dan Pemetaan Pendidik dan Tenaga Kependidikan Satuan Satuan Pendidikan Dasar, PAUD, dan PendidikanNon ormal/Kesetaraan','Kumulatif','Dokumen usulan uji kompetensi, dokumen diklat kepala sekolah, dokumen mutasi, kenaikan pangkat dan jenjang jabatan, dokumen usulan formasi dan penempatan ASN baru','Bidang PTK','Kepala Bidang PTK'),
('01-01-02-01-02-01','01-01-02-01-02','01','Jumlah Laporan Hasil Pelaksanaan Penataan Pendistribusian Pendidik dan Tenaga Kependidikan Satuan Pendidikan Dasar, PAUD, dan Pendidikan Nonformal/Kesetaraan','Laporan','1','8','8','8','8','8','Untuk mengetahui Jumlah Laporan Hasil Pelaksanaan Penataan Pendistribusian Pendidik dan Tenaga Kependidikan Satuan Pendidikan Dasar, PAUD, dan Pendidikan Non Formal/Kesetaraan','Jumlah Laporan Hasil Pelaksanaan Penataan Pendistribusian Pendidik dan Tenaga Kependidikan Satuan Pendidikan Dasar, PAUD, dan PendidikanNon normal/Kesetaraan','Kumulatif','Dokumen Pelatihan, Dokumen Pencairan Sertifikasi, Dokumen PPG, Dokumen NUPTK, Dokumen Ijin Penggunaan Gelar, Ijin Belajar, TUgas Belajar, pencairan kesra','Bidang PTK','Kepala Bidang PTK'),
('01-02-00-00-00-01','01-02-00-00-00','01','Persentase organisasi yang melaksanakan kegiatan Kepemudaan dan olahraga','Persen','','64.4','65.4','66.4','67.4','68.4','Indikator Persentase Organisasi yang Melaksanakan Kegiatan Kepemudaan dan Olahraga dipilih karena mampu mengukur tingkat keaktifan organisasi kepemudaan dan organisasi olahraga dalam menyelenggarakan kegiatan yang mendukung pengembangan potensi pemuda, peningkatan partisipasi masyarakat, serta pembinaan olahraga di daerah. Indikator ini tidak hanya menggambarkan jumlah organisasi yang terdaftar, tetapi juga menunjukkan sejauh mana organisasi tersebut berfungsi secara aktif dan memberikan kontribusi nyata terhadap pembangunan kepemudaan dan olahraga.','Persentase = (Jumlah pemuda yang menjadi anggota aktif organisasi kepemudaan ÷ Jumlah pemuda usia 16–30 tahun di wilayah tersebut) × 100%','Kumulatif','yang dimaksud dengan kegiatan organisasi kepemudaan dan olahraga adalah berbagai aktivitas yang diikuti oleh pemuda melalui organisasi kepemudaan yang bertujuan mengembangkan kapasitas, karakter, kepemimpinan, partisipasi sosial, serta kebugaran dan prestasi olahraga. dibatasi untuk organisasi kepemudaan (Muhammadiyah dan karangktaruna). Pembilang : Jumlah Pemuda usia (16-30) tahun yang menjadi anggota aktif organisasi kepemudaan dan organisasi sosial kemasyarakatan yang didirikan dan dibentuk oleh masyarakat secara sukarela berdasarkan kesamaan aspirasi, kehendak, kebutuhan, kepentingan, kegiatan dan tujuan untuk berpartisipasi dalam pembangunan demi tercapainya tujuan NKRI yang berdasarkan Pancasila. Penyebut : Jumlah pemuda (16-30) tahun di kabupaten/kota berdasarkan data kependudukan di Kabupaten/kota yang terdaftar pada Sistem Informasi Administrasi Kependudukan (SIAK). Kriteria "Anggota Aktif"organisasi dapat dikategorikan sebagai organisasi aktif apabila memenuhi beberapa kriteria, misalnya:- Terdaftar sebagai anggota organisasi.- Mengikuti kegiatan organisasi secara rutin.- Berpartisipasi dalam program kerja organisasi.- Terlibat dalam kepanitiaan atau kepengurusan.- Kehadirannya dapat dibuktikan melalui daftar hadir, kartu anggota, atau dokumentasi kegiatan.','Komite Nasional Pemuda Indonesia','Dinas Pendidikan, Kepemudaan dan Olahraga'),
('01-02-01-00-00-01','01-02-01-00-00','01','Jumlah perolehan medali pada event olahraga regional dan nasional','Persen','','30','30','30','30','30','Indikator ini digunakan untuk mengetahui jumlah perolehan medali pada event olahraga regional dan nasional','Jumlah semua perolehan medali pada event olahraga nasional dan regional','Kumulatif','Jumlah perolehan medali emas, perak dan perunggu pada event olahraga Regional dan nasional yang diikuti Pemerintah Daerah kabupaten/kota. Sesuai dengan regulasi Peraturan Pemerintah Republik Indonesia Nomor 7 Tahun 2020 Tentang Perubahan Atas Peraturan Pemerintah Nomor 17 Tahun 2007 Tentang Penyelenggaraan Pekan Dan Kejuaraan Olahraga. ruang lingkup penerima medali adalah siswa usia 10-18 tahun. 1. Penerima Medali- Atlet perorangan yang memperoleh medali emas, perak, atau perunggu.- Tim/regu yang memperoleh medali pada nomor beregu.- Kontingen daerah yang diwakili oleh atlet dari kabupaten/kota.Jenis Medali yang DihitungMedali emas, Medali perak,Medali perunggu.Tingkat Event : Regional, misalnya:Kejuaraan tingkat provinsi.Pekan Olahraga Provinsi (Porprov).Kejuaraan antarwilayah/regional yang diakui oleh induk organisasi olahraga.Tingkat event Nasional, misalnya:Kejuaraan Nasional (Kejurnas).Pekan Olahraga Nasional (PON).Event nasional resmi yang diselenggarakan oleh kementerian, komite olahraga, atau induk organisasi cabang olahraga.Cabang OlahragaSeluruh cabang olahraga yang menjadi kewenangan pembinaan pemerintah daerah dan mengikuti kejuaraan resmi.Kriteria PenghitunganHanya medali yang diperoleh pada kejuaraan resmi yang diakui oleh organisasi penyelenggara atau induk cabang olahraga.Setiap medali (emas, perak, dan perunggu) dihitung sesuai ketentuan indikator yang berlaku. Apabila indikator menggunakan jumlah medali, maka seluruh jenis medali dijumlahkan. Apabila menggunakan jumlah atlet peraih medali, maka yang dihitung adalah jumlah atlet yang memperoleh medali.','Aplikasi Silagapora','Kepala Bidang'),
('01-02-01-01-00-01','01-02-01-01-00','01','persentase kejuaraan olahraga tingkat kabupaten yang diselenggarakan','Persen','','30','31','32','33','34','Kejuaraan olahraga tingkat kabupaten merupakan kompetisi olahraga resmi yang diselenggarakan pada lingkup kabupaten dan diikuti oleh peserta yang berasal dari kecamatan, sekolah, klub olahraga, organisasi olahraga, atau kelompok masyarakat sesuai dengan ketentuan penyelenggaraan cabang olahraga.','Jumlah tlet berprestasi tingkat kabupaten dibagi jumlah seluru atlet dibagi 100%','Kumulatif','Persentase Kejuaraan Olahraga Tingkat Kabupaten yang Diselenggarakan adalah persentase jumlah kejuaraan olahraga tingkat kabupaten yang berhasil diselenggarakan oleh pemerintah daerah atau bekerja sama dengan organisasi olahraga, dibandingkan dengan jumlah kejuaraan olahraga tingkat kabupaten yang telah ditetapkan dalam dokumen perencanaan, kalender kegiatan, atau target kinerja pada tahun anggaran yang sama.Kejuaraan olahraga tingkat kabupaten merupakan kompetisi olahraga resmi yang diselenggarakan pada lingkup kabupaten dan diikuti oleh peserta yang berasal dari kecamatan, sekolah, klub olahraga, organisasi olahraga, atau kelompok masyarakat sesuai dengan ketentuan penyelenggaraan cabang olahraga.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-01-01-01-01','01-02-01-01-01','01','Jumlah Peserta pada Penyelenggaraan Kejuaraan Tingkat kabupaten/kota','Orang',' NA ','2500','2500','2500','2500','2500','indikator ini dipilih untuk mengetahui jumlah peserta pada kejuaraan dan pekan olahraga tingkat kabupaten/kota','Jumlah Dokumen Penyelenggaraan Kejuaraan dan Pekan Olahraga Tingkat Kabupaten/Kota','Kumulatif','Keikutsertaan Anggota Kontingen Kabupaten/Kota dalam Penyelenggaraan Pekan dan Kejuaraan Olahraga adalah jumlah anggota kontingen yang secara resmi mewakili pemerintah kabupaten/kota dalam mengikuti pekan olahraga, kejuaraan olahraga, atau kompetisi olahraga yang diselenggarakan pada tingkat regional, provinsi, nasional, maupun internasional selama periode pelaporan.Anggota kontingen meliputi atlet, pelatih, asisten pelatih, manajer tim, ofisial, tenaga medis, dan pendamping yang ditetapkan melalui Surat Keputusan (SK) atau dokumen resmi sebagai bagian dari kontingen kabupaten/kota.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-01-02-00-01','01-02-01-02-00','01','Prosentase cakupan pembinaan olahraga','Persen','','30','31','32','33','34','Pembinaan olahraga merupakan serangkaian kegiatan yang dilaksanakan secara terencana, berkesinambungan, dan sistematis untuk meningkatkan kemampuan, prestasi, partisipasi, serta kualitas sumber daya manusia di bidang olahraga. Pembinaan dapat mencakup olahraga pendidikan, olahraga masyarakat, dan olahraga prestasi sesuai kewenangan pemerintah daerah','Indikator ini dipilih untuk mengetahui jumlah atlet berprestasi ditingkat propinsi dibagi jumlah seluruh atlet dikali 100%','Kumulatif','Persentase Cakupan Pembinaan Olahraga adalah persentase jumlah sasaran pembinaan olahraga yang telah memperoleh layanan pembinaan dari pemerintah daerah dibandingkan dengan jumlah sasaran pembinaan olahraga yang menjadi target pada tahun anggaran yang sama.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-01-02-01-01','01-02-01-02-01','01','Jumlah penerima Penghargaan olahraga','Orang','80','300','300','300','300','300','Indikator ini dipilih untuk mengetahui jumlah Jumlah penerima Penghargaan olahraga','Jumlah penerima Penghargaan olahraga','Kumulatif','Jumlah Penerima Penghargaan Olahraga adalah jumlah individu atau kelompok yang menerima penghargaan resmi dari pemerintah, pemerintah daerah, atau lembaga yang berwenang sebagai bentuk apresiasi atas prestasi, dedikasi, kontribusi, atau pengabdian dalam bidang olahraga selama periode pelaporan.Penerima penghargaan dapat berasal dari unsur atlet, pelatih, pembina, wasit/juri, tenaga keolahragaan, organisasi olahraga, atau insan olahraga lainnya yang telah memenuhi kriteria dan ditetapkan melalui keputusan pejabat yang berwenang.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-01-03-00-01','01-02-01-03-00','01','Jumlah siswa berprestasi tingkat provinsi, nasional dan internasional','Orang','90.42528','23','25','28','31','33','Indikator ini diplih untuk mengetahui jumlah wirausaha muda, pemula dan pemuda kader kabupaten/kota','jumlah wirausaha muda pemula dan pemuda kader tingkat kabupaten dibagi seluru wirausaha dikali 100%','Kumulatif','Jumlah Siswa Berprestasi Tingkat Provinsi, Nasional, dan Internasional adalah jumlah peserta didik pada jenjang pendidikan yang menjadi kewenangan pemerintah daerah yang berhasil meraih prestasi berupa juara, medali, penghargaan, atau pengakuan resmi pada ajang kompetisi, perlombaan, festival, olimpiade, atau kegiatan akademik maupun nonakademik di tingkat provinsi, nasional, dan internasional dalam satu tahun anggaran atau tahun pelajaran.Prestasi yang dimaksud merupakan capaian yang diperoleh siswa melalui kompetisi atau seleksi yang diselenggarakan oleh pemerintah, lembaga pendidikan, organisasi profesi, atau institusi lain yang diakui secara resmi.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-01-03-01-01','01-02-01-03-01','01','Persentase pengelolaan organisasi keolahragaan di kabupaten/kota sesuai dengan standar nasional','Dokumen','1','1','1','1','1','1','Indikator ini dipilih untuk mengetahui Jumlah dokumen pengelolaan organisasi keolahragaan di kabupaten/kota sesuai standar nasional','Jumlah Dokumen pengelolaan organisasi keolahragaan di kabupaten/kota sesuai dengan standar nasional','Kumulatif','Persentase Pengelolaan Organisasi Keolahragaan di Kabupaten/Kota Sesuai dengan Standar Nasional adalah persentase organisasi keolahragaan di tingkat kabupaten/kota yang telah memenuhi standar pengelolaan organisasi sesuai dengan ketentuan peraturan perundang-undangan dan standar nasional di bidang keolahragaan, yang meliputi aspek kelembagaan, tata kelola organisasi, perencanaan program, administrasi, keuangan, sumber daya manusia, pembinaan olahraga, serta pelaporan dan akuntabilitas dalam periode pelaporan.Organisasi keolahragaan yang dimaksud meliputi organisasi olahraga prestasi, olahraga pendidikan, olahraga masyarakat, organisasi profesi keolahragaan, serta organisasi lain yang bergerak di bidang keolahragaan dan menjadi binaan pemerintah daerah sesuai kewenangannya.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-01-03-02-01','01-02-01-03-02','01','Jumlah Dokumen Hasil Peningkatan Kerja Sama Organisasi Keolahragaan Kabupaten/Kota','Dokumen',' NA','1','1','1','1','1','indikator ini dipilih untuk mengetahui jumlah dokumen hasil peningkatan kerja sama organisasi keolahragaan kabupaten/kota','Jumlah Dokumen Hasil Peningkatan Kerja Sama Organisasi Keolahragaan Kabupaten/Kota','Kumulatif','Jumlah Dokumen Hasil Peningkatan Kerja Sama Organisasi Keolahragaan Kabupaten/Kota adalah jumlah dokumen resmi yang dihasilkan dari pelaksanaan kegiatan peningkatan kerja sama antara Pemerintah Kabupaten/Kota melalui perangkat daerah yang membidangi keolahragaan dengan organisasi keolahragaan, instansi pemerintah, lembaga pendidikan, dunia usaha, organisasi profesi, maupun pemangku kepentingan lainnya dalam rangka pengembangan dan pembinaan keolahragaan selama periode pelaporan.Dokumen hasil kerja sama merupakan keluaran (output) yang menjadi bukti administratif bahwa kegiatan peningkatan kerja sama telah dilaksanakan dan menghasilkan kesepakatan, rekomendasi, rencana tindak lanjut, atau dokumen legal lainnya yang mendukung penyelenggaraan keolahragaan.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-02-00-00-01','01-02-02-00-00','01','Persentase pemuda yang menjadi anggota aktif pada organisasi kepemudaan','Persen','','81','82','83','84','85','indikator ini digunakan untuk mengetahui jumlah pemuda usia 16-30 tahun yang menjadi anggota aktif pada organisasi kepemudaan dan organisasi','Jumlah pemuda usia (16-30) tahun yang menjadi anggota aktif pada Organisasi kepemudaan dan Organisasi sosial kemasyarakatan di kabupaten/kota dibagi Jumlah pemuda usia (16-30) tahun di kabupaten/kota X 100%','Kumulatif','yang dimaksud dengan kegiatan kepemudaan dan olahraga adalah berbagai aktivitas yang diikuti oleh pemuda melalui organisasi kepemudaan yang bertujuan mengembangkan kapasitas, karakter, kepemimpinan, partisipasi sosial, serta kebugaran dan prestasi olahraga. dibatasi untuk organisasi kepemudaan (Muhammadiyah dan karangktaruna). Pembilang : Jumlah Pemuda usia (16-30) tahun yang menjadi anggota aktif organisasi kepemudaan dan organisasi sosial kemasyarakatan yang didirikan dan dibentuk oleh masyarakat secara sukarela berdasarkan kesamaan aspirasi, kehendak, kebutuhan, kepentingan, kegiatan dan tujuan untuk berpartisipasi dalam pembangunan demi tercapainya tujuan NKRI yang berdasarkan Pancasila. Penyebut : Jumlah pemuda (16-30) tahun di kabupaten/kota berdasarkan data kependudukan di Kabupaten/kota yang terdaftar pada Sistem Informasi Administrasi Kependudukan (SIAK). Kriteria "Anggota Aktif"Seseorang dapat dikategorikan sebagai anggota aktif apabila memenuhi beberapa kriteria, misalnya:- Terdaftar sebagai anggota organisasi.- Mengikuti kegiatan organisasi secara rutin.- Berpartisipasi dalam program kerja organisasi.- Terlibat dalam kepanitiaan atau kepengurusan.- Kehadirannya dapat dibuktikan melalui daftar hadir, kartu anggota, atau dokumentasi kegiatan.','Komite Nasional Pemuda Indonesia','Kepala Bidang'),
('01-02-02-01-00-01','01-02-02-01-00','01','jumlah Pemuda Pelopor','Orang','','6','6','6','6','6','Indikator ini dipilih untuk mengetahui jumlah pemuda pelopor di Kabupaten Banjarnegara','Jumlah pemuda pelopor dalam satu tahun','Kumulatif','Jumlah Pemuda Pelopor adalah jumlah pemuda yang telah ditetapkan sebagai Pemuda Pelopor berdasarkan hasil seleksi, penilaian, dan penetapan oleh pemerintah sesuai dengan ketentuan peraturan perundang-undangan dalam satu tahun anggaran.Pemuda Pelopor adalah pemuda yang memiliki kemampuan kepeloporan, inovasi, kreativitas, dedikasi, serta kontribusi nyata dalam menginisiasi perubahan positif, memberdayakan masyarakat, dan memberikan manfaat bagi pembangunan di daerahnya. Pemuda Pelopor dipilih melalui proses seleksi yang dilaksanakan secara berjenjang mulai dari tingkat kabupaten/kota, provinsi, hingga nasional sesuai dengan pedoman yang ditetapkan oleh kementerian yang membidangi urusan kepemudaan.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-02-01-01-01','01-02-02-01-01','01','Jumlah Pemuda yang di kembangkan kepemimpinan pemuda tingkat kabupaten/kota','Orang',' NA','383','385','387','389','391','Indikator ini dipilih untuk menghitung jumlah pemuda yang dikembangkan kepemimpinan pemuda tingkat kabupaten/kota','Jumlah Pemuda yang di kembangkan kepemimpinan pemuda tingkat kabupaten/kota','Kumulatif','Jumlah Pemuda yang Dikembangkan Kepemimpinan Pemuda Tingkat Kabupaten/Kota adalah jumlah pemuda yang mengikuti dan menyelesaikan program atau kegiatan pengembangan kepemimpinan yang diselenggarakan atau difasilitasi oleh pemerintah kabupaten/kota melalui perangkat daerah yang membidangi kepemudaan selama periode pelaporan, dengan tujuan meningkatkan kapasitas kepemimpinan, karakter, wawasan kebangsaan, keterampilan organisasi, kemampuan komunikasi, serta partisipasi aktif dalam pembangunan daerah.Pengembangan kepemimpinan pemuda merupakan upaya sistematis untuk membentuk pemuda yang berkarakter, berintegritas, memiliki jiwa kepemimpinan, mampu menjadi agen perubahan (agent of change), serta berkontribusi dalam kehidupan bermasyarakat, berbangsa, dan bernegara.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-02-01-02-01','01-02-02-01-02','01','Jumlah orang yang mengikuti Pengembangan Kepeloporan Pemuda bagi Pemuda Pelopor Tingkat Kabupaten/kota','Orang','','','','','','','indikator ini dipilih untuk mengetahui jumlah orang yang mengikuti pengembangan kepeloporan pemuda bagi pemuda pelopor tingkat kabupaten/kota','Jumlah orang yang mengikuti Pengembangan Kepeloporan Pemuda bagi Pemuda Pelopor Tingkat Kabupaten/kota','Kumulatif','Jumlah Orang yang Mengikuti Pengembangan Kepeloporan Pemuda bagi Pemuda Pelopor Tingkat Kabupaten/Kota adalah jumlah pemuda yang mengikuti dan menyelesaikan kegiatan pengembangan kepeloporan yang diselenggarakan atau difasilitasi oleh pemerintah kabupaten/kota dalam rangka meningkatkan kapasitas, kompetensi, jiwa kepeloporan, inovasi, kepemimpinan, dan peran aktif pemuda sebagai pelopor pembangunan di daerah selama periode pelaporan.Kegiatan pengembangan kepeloporan merupakan bagian dari pembinaan kepemudaan yang bertujuan membentuk pemuda yang mampu menjadi agen perubahan (agent of change), penggerak masyarakat, pencipta inovasi, serta teladan dalam berbagai bidang kehidupan sesuai dengan ketentuan peraturan perundang-undangan.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-02-02-00-01','01-02-02-02-00','01','Persentase organisasi kepemudaan yang mendapatkan fasilitasi dalam pengembangan organisasi .','Persen','','56','58','60','62','64','indikator ini dipilih untuk mengetahui jumlah organisasi yang mendapatkan fasilitas hibah dari Pemerintah Kabupaten Banjarnegara','jumlah organisasi yang ada dibagi jumlah yang mendapatkan fasilitasi (mendapatkan dana hibah)','Kumulatif','Persentase Organisasi Kepemudaan yang Mendapatkan Fasilitasi dalam Pengembangan Organisasi adalah persentase jumlah organisasi kepemudaan (OKP) yang memperoleh fasilitasi dari pemerintah daerah dalam rangka meningkatkan kapasitas kelembagaan, tata kelola organisasi, kompetensi sumber daya manusia, serta kualitas program kerja organisasi dibandingkan dengan jumlah organisasi kepemudaan yang menjadi sasaran pembinaan pada tahun anggaran yang sama.Organisasi kepemudaan adalah organisasi yang dibentuk oleh pemuda atau organisasi yang memiliki kepengurusan dan kegiatan yang berorientasi pada pengembangan potensi pemuda, sebagaimana diatur dalam ketentuan peraturan perundang-undangan tentang kepemudaan.Fasilitasi dalam pengembangan organisasi merupakan dukungan yang diberikan oleh pemerintah daerah untuk meningkatkan kapasitas organisasi kepemudaan agar mampu menjalankan fungsi organisasi secara efektif, mandiri, dan berkelanjutan.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-02-02-01-01','01-02-02-02-01','01','Jumlah Koordinasi, sinkronisasi, dan penyelenggaran pengembangan organisasi kepemudaan tingkat kabupaten/kota','Organisasi','','2','2','2','2','2','Untuk mengetahui Jumlah Koordinasi, sinkronisasi, dan penyelenggaran pengembangan organisasi kepemudaan tingkat kabupaten/kota','Jumlah Koordinasi, sinkronisasi, dan penyelenggaran pengembangan organisasi kepemudaan tingkat kabupaten/kota','Kumulatif','Jumlah Koordinasi, Sinkronisasi, dan Penyelenggaraan Pengembangan Organisasi Kepemudaan Tingkat Kabupaten/Kota adalah jumlah kegiatan koordinasi, sinkronisasi, dan penyelenggaraan yang dilaksanakan oleh pemerintah kabupaten/kota melalui perangkat daerah yang membidangi kepemudaan dalam rangka meningkatkan kapasitas, tata kelola, jejaring, kemitraan, dan peran organisasi kepemudaan di tingkat kabupaten/kota selama periode pelaporan.Kegiatan tersebut bertujuan untuk menyelaraskan program dan kebijakan, memperkuat kelembagaan organisasi kepemudaan, meningkatkan sinergi antarorganisasi dan pemangku kepentingan, serta mendukung partisipasi aktif pemuda dalam pembangunan daerah.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-03-00-00-01','01-02-03-00-00','01','Jumlah pramuka garuda','Orang','100','2710','2715','2720','2725','2730','Indikator ini digunakan untuk mengetahui kegiatan kepramukaan yang diselenggarakan di sekolah','umlah anggota Gerakan Pramuka yang ditetapkan sebagai Pramuka Garuda dalam satu tahun.','Kumulatif','tingkatan tertinggi dalam Gerakan Pramuka di Indonesia, yang menunjukkan bahwa seorang anggota Pramuka telah mencapai tingkat kecakapan dan penguasaan keterampilan yang sangat tinggi dalam kepramukaan. Jumlah Pramuka Garuda adalah jumlah anggota muda Gerakan Pramuka yang telah memenuhi seluruh persyaratan sesuai golongan usianya (Siaga, Penggalang, Penegak, atau Pandega), telah lulus uji Pramuka Garuda, dan telah ditetapkan secara resmi melalui Surat Keputusan (SK) Kwartir Gerakan Pramuka yang berwenang dalam satu tahun berjalan. Pramuka Garuda merupakan penghargaan tertinggi bagi peserta didik Gerakan Pramuka pada setiap golongan usia. Yang termasuk dalam indikator ini adalah:- Pramuka Siaga Garuda.- Pramuka Penggalang Garuda.- Pramuka Penegak Garuda.- Pramuka Pandega Garuda. Anggota Pramuka dihitung apabila:Telah memenuhi seluruh persyaratan Pramuka Garuda sesuai golongannya.Telah mengikuti proses penilaian atau uji Pramuka Garuda.Telah memperoleh SK Penetapan Pramuka Garuda dari Kwartir yang berwenang.Ditetapkan pada tahun pengukuran kinerja','Dinas Pendidikan, Kepemudaan dan Olahraga','Kepala Bidang'),
('01-02-03-01-00-01','01-02-03-01-00','01','jumlah kegiatan pengembangan kepramukaan yang diselenggarakan setiap tahun','Jumlah','','3','3','3','3','3','indikator ini dipilih untuk mengetahui Jumlah kegiatan peningkatan kapasitas kepramukaan. egiatan pengembangan kepramukaan merupakan kegiatan yang dirancang untuk mendukung pembinaan anggota Gerakan Pramuka, baik peserta didik maupun pembina, pelatih, dan pengurus, sesuai dengan tujuan pendidikan kepramukaan sebagaimana diatur dalam ketentuan peraturan perundang-undangan.','Jumlah kegiatan peningkatan kapasitas kepramukaan','Kumulatif','Jumlah Kegiatan Pengembangan Kepramukaan yang Diselenggarakan Setiap Tahun adalah jumlah kegiatan kepramukaan yang diselenggarakan atau difasilitasi oleh pemerintah daerah dalam satu tahun anggaran sebagai upaya meningkatkan kapasitas, keterampilan, karakter, kepemimpinan, serta peran aktif anggota Gerakan Pramuka dalam pembangunan daerah.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-02-03-01-01-01','01-02-03-01-01','01','Jumlah Organisasi Kepramukaan Tingkat Daerah yang Meningkat Kapasitasnya','organisasi','1','5','5','5','5','5','Untuk mengetahui Jumlah Organisasi Kepramukaan Tingkat Daerah yang Meningkat Kapasitasnya','Jumlah Organisasi Kepramukaan Tingkat Daerah yang Meningkat Kapasitasnya','Kumulatif','Jumlah Organisasi Kepramukaan Tingkat Daerah yang Meningkat Kapasitasnya adalah jumlah gugus depan, kwartir ranting, kwartir cabang, atau organisasi kepramukaan lainnya di tingkat kabupaten/kota yang mengalami peningkatan kapasitas kelembagaan, manajemen, sumber daya manusia, dan/atau program kerja melalui kegiatan pembinaan, pelatihan, bimbingan teknis, pendampingan, serta fasilitasi dari pemerintah daerah atau kwartir yang lebih tinggi selama periode pelaporan.Peningkatan kapasitas organisasi kepramukaan dimaksudkan sebagai kondisi dimana organisasi pramuka menunjukkan perbaikan dalam aspek tata kelola organisasi, pelaksanaan program kepramukaan, kompetensi pembina, administrasi organisasi, serta keaktifan kegiatan kepramukaan berdasarkan hasil monitoring dan evaluasi atau instrumen penilaian yang ditetapkan.','Bidang Kepemudaan dan Olahraga','Kepala Bidang Kepemudaan dan Olahraga'),
('01-03-00-00-00-01','01-03-00-00-00','01','Indeks Pelayanan Publik','Indeks','3.43','3.6','4','4.1','4.2','4.3','Indikator ini dipilih untuk mengukur tingkat kepatuhan instansi terhadap standar pelayanan publik','asil Penilaian Tim PEKPPP (Pemantauan dan Evaluasi Kinerja Penyelenggaraan Pelayanan Publik)','Kumulatif','Total Nilai Persepsi per unsur dibagi total unsur yang terisi kali nilai penimbang. (PEKPPP) untuk mengukur kinerja penyelenggaraan pelayanan publik secara nasional. Aspek penilaian yang menjadi indikator dalam perhitungan. IPP dalam PEKPPP adalah sebagai berikut: 1. Kebijakan Pelayanan (24%) 2. Profesionalisme SDM (25%) 3. Sarana Prasarana (18%) 4. Sistem Informasi Pelayanan Publik (10%) 5. Konsultasi Pengaduan (11%) 6. Inovasi (12%) Adapun penilaian dilakukan melalui 3 formulir: -Formulir 01: Pengisian Bukti dukung (Bobot 0%) - Formulir 02: Penilaian Ahli (Bobot 75%) -Formulir 03: Persepsi Masyarakat Pengguna Layanan (Bobot 25%) Rentang nilai: 0-5 4,515,00 (A) Pelayanan Prima 4,01-4,50 (A-) Sangat Baik 3,51-4,00 (B) = Baik 3,01-3,50 (B-) Baik dengan Catatan 2,513,00 (C) Cukup 2,01-2,50 (C) Cukup dengan Catatan 1,512,00 (D) Prioritas Pembinaan 1,011,50 (E) Prioritas Pembinaan 0-1,00 (F) Prioritas Pembinaan','Data dari Bagian Organisasi Setda Kab. Banjarnegara','Dinas Pendidikan, Kepemudaan dan Olahraga'),
('01-03-00-00-00-02','01-03-00-00-00','02','Nilai SAKIP DINDIKPORA','Angka','71.35','72.45','72.85','73.35','73.85','74.35','Sebagai fondasi utama dalam mewujudkan pemerintahan yang akuntabel, efisien, efektif, transparan, dan berorientasi hasil','Kategori penilaian atas Dokumen SAKIP Pemerintah Kabupaten Banjarnegara','Kumulatif','Nilai SAKIP OPD adalah skor atau tingkat capaian akuntabilitas kinerja yang diberikan kepada Organisasi Perangkat Daerah (OPD) dalam rangka pelaksanaan Sistem Akuntabilitas Kinerja Instansi Pemerintah (SAKIP).','LHE SAKIP Inpsektorat','Dinas Pendidikan, Kepemudaan dan Olahraga'),
('01-03-01-00-00-01','01-03-01-00-00','01','Persentase tingkat pelayanan umum, kepegawaian, dan keuangan perangkat daerah','Persen','100','100','100','100','100','100','Untuk Mengukur efektivitas layanan administratif perangkat daerah','Jumlah pelayanan umum, kepegawaian, dankeuangan------------------------ x 100Jumlah pelayanan umum, kepegawaian, dankeuangan yang direncanakan','Kumulatif','Persentase tingkat pelayanan umum, kepegawaian, dan keuangan perangkat daerah adalah ukuran yang menunjukkan tingkat pencapaian pelayanan administratif yang meliputi layanan umum, pengelolaan kepegawaian, dan pengelolaan keuangan yang dilaksanakan oleh perangkat daerah, dibandingkan dengan target yang telah ditetapkan dalam dokumen perencanaan atau standar pelayanan.','Sekretariat','Sekretaris'),
('01-03-01-01-00-01','01-03-01-01-00','01','Persentase Dokumen Administrasi Keuangan yang akuntabel dan tepat waktu','Persen','100','100','100','100','100','100','Indikator ini dipilih untuk mengetahui jumlah dokumen keuangan yang terseda. Indikator ini digunakan untuk mengukur kualitas tata kelola administrasi keuangan perangkat daerah, khususnya dalam aspek:Akuntabilitas, yaitu kesesuaian dokumen dengan ketentuan peraturan, kelengkapan administrasi, kebenaran data, dan dapat dipertanggungjawabkan.Ketepatan waktu, yaitu penyampaian dokumen sesuai jadwal atau batas waktu yang telah ditentukan dalam peraturan perundang-undangan maupun ketentuan pemerintah daerah.','jumlah dokumen keuangan yang tersedia','Kumulatif','Persentase Dokumen Administrasi Keuangan yang Akuntabel dan Tepat Waktu adalah persentase jumlah dokumen administrasi keuangan yang disusun, diperiksa, disahkan, dan disampaikan secara lengkap, benar, sesuai dengan ketentuan peraturan perundang-undangan (akuntabel), serta disampaikan sesuai batas waktu yang telah ditetapkan dibandingkan dengan jumlah seluruh dokumen administrasi keuangan yang wajib disusun dan disampaikan dalam satu tahun anggaran.','Sekretariat','Sekretaris'),
('01-03-01-01-01-01','01-03-01-01-01','01','Jumlah Orang yang Menerima Gaji danTunjangan ASN','Orang/bulan','5514','5566','5566','5566','5566','5566','Indikator ini dipilih untuk mengetahui capaian kinerja sub kegiatan Koordinasi Penyediaan Gaji dan Tunjangan ASN','Jumlah Orang yang Menerima Gaji dan Tunjangan ASN','Kumulatif','Koordinasi Penyediaan Gaji dan Tunjangan ASN adalah kegiatan koordinasi antar-perangkat daerah untuk memastikan penyediaan, penghitungan, dan penyaluran gaji serta tunjangan Aparatur Sipil Negara (ASN) dilakukan tepat waktu dan sesuai ketentuan peraturan perundang-undangan.','Sekretariat','Sekretaris'),
('01-03-01-01-02-01','01-03-01-01-02','01','Jumlah Dokumen Penatausahaan danPengujian/Verifikasi Keuangan SKPD','Dokumen','1','1','1','1','1','1','Indikator ini dipilih untuk mengetahui capaian kinerja sub kegiatan Pelaksanaan Penatausahaan dan Pengujian/Verifikasi Keuangan SKPD','Jumlah Dokumen Penatausahaan dan Pengujian/Verifikasi Keuangan SKPD','Kumulatif','Pelaksanaan Penatausahaan dan Pengujian/Verifikasi Keuangan SKPD adalah kegiatan penatausahaan serta pengujian dan verifikasi administrasi keuangan SKPD untuk memastikan akurasi, akuntabilitas, dan kepatuhan terhadap peraturan yang berlaku.','Sekretariat','Sekretaris'),
('01-03-01-01-03-01','01-03-01-01-03','01','Jumlah Laporan Keuangan Bulanan/ Triwulanan/ Semesteran SKPD dan Laporan Koordinasi Penyusunan Laporan Keuangan Bulanan/Triwulanan/Semesteran SKPD','Laporan','1','1','1','1','1','1','Indikator ini dipilih untuk mengetahui capaian kinerja sub kegiatan Koordinasi dan Penyusunan Laporan Keuangan Akhir Tahun SKPD','Jumlah Laporan Keuangan SKPD','Kumulatif','Koordinasi dan Penyusunan Laporan Keuangan Akhir Tahun SKPD adalah kegiatan koordinasi dan penyusunan laporan keuangan akhir tahun SKPD yang memuat informasi tentang realisasi anggaran, aset, kewajiban, dan ekuitas untuk mendukung penyajian laporan keuangan pemerintah daerah.','Sekretariat','Sekretaris'),
('01-03-01-02-00-01','01-03-01-02-00','01','Persentase terpenuhnya dokumen administrasi Umum Perangkat Daerah','Persen','100','100','100','100','100','100','Indikator ini dipilih untuk mengetahui jumlah pelayanan administrasi perkantoran','Jumlah pelayanan administrasi perkantoran','Kumulatif','Persentase Terpenuhinya Dokumen Administrasi Umum Perangkat Daerah adalah persentase jumlah dokumen administrasi umum yang wajib disusun, dikelola, dan tersedia oleh perangkat daerah sesuai dengan ketentuan peraturan perundang-undangan yang telah dipenuhi secara lengkap, benar, tertib administrasi, dan tepat waktu dibandingkan dengan jumlah seluruh dokumen administrasi umum yang menjadi kewajiban perangkat daerah dalam satu tahun anggaran.','Sekretariat','Sekretaris'),
('01-03-01-02-01-01','01-03-01-02-01','01','Jumlah Paket Komponen InstalasiListrik/Penerangan Bangunan Kantor yang Disediakan','Paket','1','1','1','1','1','1','Indikator ini dipilih untuk mengetahui capaian kinerja sub kegiatan Penyediaan Peralatan dan Perlengkapan Kantor','Jumlah Paket Komponen Instalasi Listrik/Penerangan Bangunan Kantor yang Disediakan','Kumulatif','Penyediaan Peralatan dan Perlengkapan Kantor adalah kegiatan penyediaan peralatan serta perlengkapan kerja yang diperlukan untuk mendukung operasional kantor dan kelancaran pelaksanaan tugas pemerintahan.','Sekretariat','Sekretaris'),
('01-03-01-02-02-01','01-03-01-02-02','01','Jumlah Paket Peralatan dan PerlengkapanKantor yang Disediakan','Paket','1','1','1','1','1','1','Indikator ini dipilih untuk mengetahui capaian kinerja sub kegiatan Penyediaan Peralatan dan Perlengkapan Kantor','Jumlah Paket Peralatan dan Perlengkapan Kantor yang Disediakan','Kumulatif','Penyediaan Peralatan dan Perlengkapan Kantor adalah kegiatan penyediaan peralatan serta perlengkapan kerja yang diperlukan untuk mendukung operasional kantor dan kelancaran pelaksanaan tugas pemerintahan','Sekretariat','Sekretaris'),
('01-03-01-02-03-01','01-03-01-02-03','01','Jumlah Paket Peralatan Rumah Tangga yangDisediakan','Paket','1','1','1','1','1','1','Untuk mengetahui Jumlah Paket peralatan Rumah Tangga yang Disediakan','Jumlah Paket Peralatan Rumah Tangga yang Disediakan','Kumulatif','Jumlah Paket Peralatan Rumah Tangga yang Disediakan adalah jumlah paket peralatan rumah tangga yang diadakan dan disediakan oleh perangkat daerah untuk mendukung operasional kantor, rumah dinas, atau fasilitas pemerintah sesuai dengan standar kebutuhan dan ketentuan peraturan perundang-undangan selama periode pelaporan.Paket peralatan rumah tangga merupakan satu kesatuan barang yang digunakan untuk menunjang kebersihan, kenyamanan, keamanan, dan kelancaran operasional fasilitas milik pemerintah. Penyediaan dapat dilakukan melalui pengadaan, pembelian, atau mekanisme lain yang sah sesuai ketentuan.','Sekretariat','Sekretaris'),
('01-03-01-02-04-01','01-03-01-02-04','01','Jumlah Paket Bahan Logistik Kantor yangDisediakan','Paket','1','1','1','1','1','1','Indikator ini dipilih untuk mengetahui capaian kinerja sub kegiatan Penyediaan Bahan Logistik Kantor','Jumlah Paket Bahan Logistik Kantor yang Disediakan','Kumulatif','Penyediaan Bahan Logistik Kantor adalah kegiatan pengadaan berbagai bahan logistik kantor seperti alat tulis kantor (ATK), bahan habis pakai, serta kebutuhan penunjang lainnya untuk mendukung efisiensi operasional dan pelayanan publik.','Sekretariat','Sekretaris'),
('01-03-01-02-05-01','01-03-01-02-05','01','Jumlah Dokumen Hasil Koordinasi dan Pelaksanaaan Sistem Informasi Kepegawaian','Laporan','1','1','1','1','1','1','Untuk mengetahui Jumlah Dokumen Hasil Koordinasi dan Pelaksanaaan Sistem Informasi Kepegawaian','Jumlah Dokumen Hasil Koordinasi dan Pelaksanaaan Sistem Informasi Kepegawaian','Kumulatif','Jumlah Dokumen Hasil Koordinasi dan Pelaksanaan Sistem Informasi Kepegawaian adalah jumlah dokumen resmi yang dihasilkan dari kegiatan koordinasi, sinkronisasi, pengelolaan, pemutakhiran, pengembangan, monitoring, evaluasi, dan pelaksanaan sistem informasi kepegawaian yang dilaksanakan oleh perangkat daerah selama periode pelaporan.Dokumen tersebut merupakan bukti administratif bahwa kegiatan koordinasi dan pelaksanaan sistem informasi kepegawaian telah dilaksanakan untuk mendukung pengelolaan data Aparatur Sipil Negara (ASN) yang akurat, mutakhir, terpadu, dan dapat dipertanggungjawabkan','Dinas Pendidikan, Kepemudaan dan Olahraga','Sekretaris'),
('01-03-01-02-06-01','01-03-01-02-06','01','Jumlah Dokumen Monitoring, Evaluasi, danPenilaian Kinerja Pegawai','Laporan','1','1','1','1','1','1','Untuk mengetahui Jumlah Dokumen Monitoring, Evaluasi, dan Penilaian Kinerja Pegawai','Jumlah Dokumen Monitoring, Evaluasi, dan Penilaian Kinerja Pegawai','Kumulatif','Jumlah Dokumen Monitoring, Evaluasi, dan Penilaian Kinerja Pegawai adalah jumlah dokumen resmi yang dihasilkan dari pelaksanaan kegiatan monitoring, evaluasi, dan penilaian kinerja Aparatur Sipil Negara (ASN) dan/atau pegawai lainnya di lingkungan perangkat daerah selama periode pelaporan. Dokumen tersebut menjadi bukti administratif atas pelaksanaan pemantauan, pengukuran, analisis, dan evaluasi capaian kinerja pegawai sesuai dengan ketentuan peraturan perundang-undangan.Monitoring dilakukan untuk memantau pelaksanaan tugas dan pencapaian target kinerja pegawai, evaluasi dilakukan untuk menilai efektivitas pelaksanaan tugas serta mengidentifikasi permasalahan dan perbaikan, sedangkan penilaian kinerja merupakan proses pengukuran capaian kinerja pegawai berdasarkan indikator kinerja individu dan perilaku kerja.','Sekretariat','Sekretaris'),
('01-03-01-03-00-01','01-03-01-03-00','01','Persentase terpenuhinya penyedaan jasa penunjang urusan pemerintah daerah','Persen','100','100','100','100','100','100','Indikator ini dipilih untuk mengetahui Jumlah penyediaan jasa pelayanan kantor','Jumlah penyediaan jasa pelayanan kantor','Kumulatif','Persentase Terpenuhinya Penyediaan Jasa Penunjang Urusan Pemerintahan Daerah adalah persentase jenis jasa penunjang yang berhasil disediakan sesuai dengan kebutuhan operasional perangkat daerah dibandingkan dengan jumlah jenis jasa penunjang yang telah direncanakan atau ditetapkan dalam dokumen perencanaan dan penganggaran pada tahun anggaran yang sama.Jasa penunjang urusan pemerintahan daerah adalah jasa yang diperlukan untuk mendukung kelancaran penyelenggaraan tugas, fungsi, pelayanan publik, dan administrasi pemerintahan pada perangkat daerah. Penyediaan jasa dilakukan sesuai kebutuhan operasional serta ketentuan peraturan perundang-undangan di bidang pengelolaan keuangan daerah dan pengadaan barang/jasa pemerintah.','Sekretariat','Sekretaris'),
('01-03-01-03-01-01','01-03-01-03-01','01','Jumlah Laporan Penyediaan Jasa Komunikasi, Sumber Daya Air dan Listrik yang Disediakan','Laporan','1','1','1','1','1','1','Untuk mengetahui Jumlah Laporan Penyediaan Jasa Komunikasi, Sumber Daya Air dan Listrik yang Disediakan','Jumlah Laporan Penyediaan Jasa Komunikasi, Sumber Daya Air dan Listrik yang Disediakan','Kumulatif','Jumlah Laporan Penyediaan Jasa Komunikasi, Sumber Daya Air dan Listrik yang Disediakan adalah jumlah laporan resmi yang disusun sebagai hasil pelaksanaan penyediaan jasa komunikasi, sumber daya air, dan listrik untuk mendukung operasional perangkat daerah selama periode pelaporan.Laporan tersebut memuat informasi mengenai perencanaan, realisasi penggunaan, pembayaran, pemanfaatan, pengendalian, dan evaluasi penyediaan layanan komunikasi, air, dan listrik yang digunakan untuk menunjang penyelenggaraan tugas dan fungsi perangkat daerah.','Sekretariat','Sekretaris'),
('01-03-01-03-02-01','01-03-01-03-02','01','Jumlah Laporan Penyediaan Jasa PelayananUmum Kantor yang Disediakan','Laporan','1','1','1','1','1','1','Untuk mengetahui Jumlah Laporan Penyediaan Jasa Pelayanan Umum Kantor yang Disediakan','Jumlah Laporan Penyediaan Jasa Pelayanan Umum Kantor yang Disediakan','Kumulatif','Jumlah Laporan Penyediaan Jasa Pelayanan Umum Kantor yang Disediakan adalah jumlah laporan resmi yang disusun sebagai hasil pelaksanaan penyediaan jasa pelayanan umum kantor untuk mendukung kelancaran operasional perangkat daerah selama periode pelaporan.Laporan tersebut memuat informasi mengenai perencanaan, pelaksanaan, realisasi, penggunaan anggaran, serta hasil penyediaan jasa pelayanan umum kantor yang dilaksanakan sesuai dengan ketentuan peraturan perundang-undangan.','Sekretariat','Sekretaris'),
('01-03-01-04-00-01','01-03-01-04-00','01','Persentase terpenuhinya Pemeliharaan Barang Milik Daerah Penunjang Urusan Pemerintahan Daerah','Persen','100','100','100','100','100','100','ndikator ini digunakan untuk mengukur tingkat keberhasilan perangkat daerah dalam memenuhi kebutuhan pemeliharaan aset yang digunakan untuk mendukung pelayanan publik dan penyelenggaraan pemerintahan.','total persepsi per unsur dibagi total unsur yang terisi dikali 100%','Kumulatif','ersentase Terpenuhinya Pemeliharaan Barang Milik Daerah (BMD) Penunjang Urusan Pemerintahan Daerah adalah persentase jumlah Barang Milik Daerah (BMD) yang menjadi penunjang penyelenggaraan urusan pemerintahan daerah dan telah dilakukan pemeliharaan sesuai dengan rencana kebutuhan pemeliharaan, standar operasional, serta ketentuan peraturan perundang-undangan dibandingkan dengan jumlah seluruh Barang Milik Daerah yang direncanakan untuk dipelihara dalam satu tahun anggaran.Pemeliharaan Barang Milik Daerah merupakan seluruh kegiatan yang dilakukan untuk menjaga, merawat, memperbaiki, dan mempertahankan kondisi Barang Milik Daerah agar tetap berfungsi secara optimal, aman, laik pakai, memiliki umur manfaat sesuai ketentuan, serta mendukung kelancaran penyelenggaraan tugas dan fungsi perangkat daerah.','Sekretariat','Sekretaris'),
('01-03-01-04-01-01','01-03-01-04-01','01','Jumlah Kendaraan Dinas Operasional atau Lapangan yang Dipelihara dan dibayarkan Pajak dan Perizinannya','Unit','10','12','13','14','15','16','Untuk mengetahui Jumlah Kendaraan Dinas Operasional atau Lapangan yang Dipelihara dan dibayarkan Pajak dan Perizinannya','Jumlah Kendaraan Dinas Operasional atau Lapangan yang Dipelihara dan dibayarkan Pajak dan Perizinannya','Kumulatif','Jumlah Kendaraan Dinas Operasional atau Lapangan yang Dipelihara dan Dibayarkan Pajak serta Perizinannya adalah jumlah seluruh unit kendaraan dinas milik atau yang dikuasai oleh perangkat daerah yang telah memperoleh layanan pemeliharaan rutin maupun berkala, serta telah dilakukan pembayaran kewajiban pajak kendaraan bermotor dan pengurusan dokumen perizinan sesuai ketentuan yang berlaku dalam satu tahun anggaran.','Sekretariat','Sekretaris'),
('01-03-01-04-02-01','01-03-01-04-02','01','Jumlah Gedung Kantor dan Bangunan Lainnyayang Dipelihara/Direhabilitasi','Unit','2','3','4','5','6','7','Untuk mengetahui Jumlah Gedung Kantor dan Bangunan Lainnyayang Dipelihara/Direhabilitasi','Jumlah Gedung Kantor dan Bangunan Lainnya yang Dipelihara/Direhabilitasi','Kumulatif','Jumlah Gedung Kantor dan Bangunan Lainnya yang Dipelihara/Direhabilitasi adalah jumlah unit gedung kantor dan bangunan lainnya yang menjadi aset atau berada dalam pengelolaan perangkat daerah yang telah dilakukan kegiatan pemeliharaan dan/atau rehabilitasi untuk mempertahankan atau mengembalikan fungsi, keamanan, kenyamanan, dan kelayakan bangunan sesuai standar teknis dalam satu tahun anggaran.','Sekretariat','Sekretaris'),
('01-03-01-04-03-01','01-03-01-04-03','01','Jumlah Sarana dan Prasarana Gedung Kantor atau Bangunan Lainnyayang Dipelihara/Direhabilitasi','Unit','5','5','7','9','11','13','Untuk mengetahui Jumlah Gedung Kantor dan Bangunan Lainnya yang Dipelihara/Direhabilitasi','Jumlah Gedung Kantor dan Bangunan Lainnya yang Dipelihara/Direhabilitasi','Kumulatif','Jumlah Sarana dan Prasarana Gedung Kantor atau Bangunan Lainnya yang Dipelihara/Direhabilitasi adalah jumlah unit sarana dan prasarana yang berada di dalam atau menjadi bagian dari gedung kantor maupun bangunan lainnya milik atau yang dikelola oleh perangkat daerah yang telah dilakukan kegiatan pemeliharaan dan/atau rehabilitasi sehingga tetap berfungsi secara optimal, aman, nyaman, dan mendukung kelancaran penyelenggaraan tugas pemerintahan dalam satu tahun anggaran.','Sekretariat','Sekretaris'),
('01-03-01-05-00-01','01-03-01-05-00','01','Persentase Terpenuhinya Pengadaan Barang Milik Daerah Penunjang urusan Pemerintah Daerah','Persen','100','100','100','100','100','100','Indikator ini mengukur tingkat keberhasilan perangkat daerah dalam memenuhi kebutuhan sarana, prasarana, peralatan, dan aset tetap lainnya yang telah direncanakan dalam dokumen perencanaan dan penganggaran.','total persepsi per unsur dibagi total unsur yang terisi dikali 100%','Kumulatif','Persentase Terpenuhinya Pengadaan Barang Milik Daerah (BMD) Penunjang Urusan Pemerintahan Daerah adalah persentase jumlah Barang Milik Daerah (BMD) yang berhasil diadakan sesuai dengan rencana kebutuhan, spesifikasi teknis, jumlah, kualitas, dan waktu pelaksanaan dibandingkan dengan jumlah Barang Milik Daerah yang direncanakan untuk diadakan dalam satu tahun anggaran.Pengadaan Barang Milik Daerah merupakan rangkaian kegiatan untuk memperoleh barang melalui pembelian, pembangunan, hibah, tukar-menukar, atau cara lain yang sah sesuai dengan ketentuan peraturan perundang-undangan, guna mendukung penyelenggaraan urusan pemerintahan, pelaksanaan tugas dan fungsi perangkat daerah, serta pelayanan kepada masyarakat.','Sekretariat','Sekretaris'),
('01-03-01-05-01-01','01-03-01-05-01','01','Jumlah Unit Kendaraan Perorangan Dinas atau Kendaraan Dinas Jabatan yang Disediakan','Unit','1','0','1','1','1','1','Untuk mengetahui Jumlah Unit Kendaraan Perorangan Dinas atau Kendaraan Dinas Jabatan yang Disediakan','Jumlah Unit Kendaraan Perorangan Dinas atau Kendaraan Dinas Jabatan yang Disediakan','Kumulatif','Jumlah Unit Kendaraan Perorangan Dinas atau Kendaraan Dinas Jabatan yang Disediakan adalah jumlah unit kendaraan bermotor milik atau yang dikuasai oleh pemerintah daerah yang disediakan untuk mendukung pelaksanaan tugas, fungsi, dan tanggung jawab pejabat yang berhak menerima fasilitas kendaraan perorangan dinas atau kendaraan dinas jabatan sesuai dengan ketentuan peraturan perundang-undangan dalam satu tahun anggaran.','Sekretariat','Sekretaris'),
('01-03-01-05-02-01','01-03-01-05-02','01','Jumlah Unit Aset Tetap Lainnya yang Disediakan','Unit','1','0','1','1','1','1','Untuk mengetahui Jumlah Unit Aset Tetap Lainnya yang Disediakan','Jumlah Unit Aset Tetap Lainnya yang Disediakan','Kumulatif','Jumlah Unit Aset Tetap Lainnya yang Disediakan adalah jumlah unit aset tetap yang termasuk dalam kelompok Aset Tetap Lainnya sesuai dengan ketentuan Standar Akuntansi Pemerintahan (SAP) dan pengelolaan Barang Milik Daerah (BMD), yang berhasil disediakan melalui pengadaan, pembangunan, hibah, atau mekanisme perolehan lainnya yang sah dalam satu tahun anggaran untuk mendukung penyelenggaraan tugas dan fungsi perangkat daerah. Aset Tetap Lainnya merupakan aset berwujud yang memiliki masa manfaat lebih dari 12 (dua belas) bulan, digunakan dalam kegiatan pemerintahan, namun tidak termasuk kategori tanah, peralatan dan mesin, gedung dan bangunan, jalan, irigasi dan jaringan, maupun konstruksi dalam pengerjaan.','Sekretariat','Sekretaris'),
('01-03-01-05-03-01','01-03-01-05-03','01','Jumlah Unit Sarana dan Prasarana Gedung Kantor atau Bangunan Lainnya yang Disediakan','Unit','1','1','2','3','4','5','Indikator ini dipilih untuk mengetahui capaian kinerja sub kegiatan Pengadaan Sarana dan Prasarana Gedung Kantor atau Bangunan Lainnya','Jumlah Unit Sarana dan Prasarana Gedung Kantor atau Bangunan Lainnya yang Disediakan','Kumulatif','Jumlah Unit Sarana dan Prasarana Gedung Kantor atau Bangunan Lainnya yang Disediakan adalah jumlah unit sarana dan prasarana pendukung gedung kantor atau bangunan lainnya yang berhasil disediakan melalui pengadaan, pembangunan, penggantian, hibah, atau mekanisme perolehan lainnya yang sah dalam satu tahun anggaran untuk mendukung penyelenggaraan tugas dan fungsi perangkat daerah serta meningkatkan kualitas pelayanan publik. Sarana dan prasarana gedung merupakan fasilitas yang melekat pada atau berada di lingkungan gedung kantor maupun bangunan lainnya sehingga mendukung operasional, keamanan, kenyamanan, dan kelancaran pelaksanaan pekerjaan.','Sekretariat','Sekretaris'),
('01-03-02-00-00-01','01-03-02-00-00','01','Persentase tingkat ketercapaian kinerja perangkat daerah','Persen','100','100','100','100','100','100','Untuk menunjukkan sejauh mana perangkat daerah berhasil mencapai target-target yang telah ditetapkan.','Jumlah dokumen perencanaan dan pelaporan yangdisusun------------------------ x 100Jumlah dokumen perencanaan dan pelaporan dalamSAKIP','Kumulatif','Persentase tingkat ketercapaian kinerja perangkat daerah adalah ukuran yang menunjukkan perbandingan antara realisasi capaian kinerja (output atau outcome) perangkat daerah dengan target kinerja yang telah ditetapkan','LHE SAKIP atas reviu Inspektorat Daerah Kab. Banjarnegara','Sekrataris'),
('01-03-02-01-00-01','01-03-02-01-00','01','Persentase terpenuhinya dokumen Perencanaan, Penganggaran, dan Evaluasi Kinerja Perangkat Daerah yang berkualitas dan tepat waktu','Persen','100','100','100','100','100','100','Indikator ini dipilih untuk mengetahui capaian kinerjakegiatan Perencanaan, Penganggaran, dan Evaluasi KinerjaPerangkat Daerah','Jumlah dokumen perencanaan dan pelaporan yangdisusun------------------------ x 100Jumlah dokumen perencanaan dan pelaporan dalamSAKIP','Kumulatif','Kegiatan Perencanaan, Penganggaran, dan Evaluasi Kinerja Perangkat Daerah adalah proses yang dilakukan oleh perangkat daerah untuk menyusun rencana kerja, mengalokasikan anggaran, dan melakukan evaluasi terhadap pelaksanaan program kerja. Ukurannya didasarkan pada jumlah dokumen perencanaan, laporan penganggaran, dan hasil evaluasi yang dilaporkan dalam satu tahun','Sekretariat','Sekretaris'),
('01-03-02-01-01-01','01-03-02-01-01','01','Jumlah Dokumen Perencanaan Perangkat daerah','Dokumen','7','9','9','9','9','9','indikator ini dipilih untuk mengetahui Jumlah Dokumen Perencanaan Perangkat daerah','Jumlah Dokumen Perencanaan Perangkat daerah','Kumulatif','Jumlah Dokumen Perencanaan Perangkat Daerah adalah jumlah dokumen perencanaan yang disusun, dibahas, ditetapkan, dan/atau dilaporkan oleh perangkat daerah sesuai dengan ketentuan peraturan perundang-undangan dalam satu tahun anggaran sebagai dasar pelaksanaan, pengendalian, dan evaluasi kinerja perangkat daerah.Dokumen perencanaan merupakan dokumen resmi yang memuat arah kebijakan, sasaran, program, kegiatan, subkegiatan, target kinerja, kebutuhan pendanaan, serta indikator kinerja yang menjadi pedoman pelaksanaan tugas dan fungsi perangkat daerah','Sekretariat','Sekretaris'),
('01-03-02-01-02-01','01-03-02-01-02','01','Jumlah Laporan Capaian Kinerja dan Ikhtisar Realisasi Kinerja SKPD dan Laporan Hasil Koordinasi Penyusunan Laporan Capaian Kinerja dan Ikhtisar Realisasi Kinerja SKPD','Dokumen','0','7','7','7','7','7','indikator ini dipilih untuk mengetahui Jumlah Laporan Capaian Kinerja dan Ikhtisar Realisasi Kinerja SKPD dan Laporan Hasil Koordinasi Penyusunan Laporan Capaian Kinerja dan Ikhtisar Realisasi Kinerja SKPD','Jumlah Laporan Capaian Kinerja dan Ikhtisar Realisasi Kinerja SKPD dan Laporan Hasil Koordinasi Penyusunan Laporan Capaian Kinerja dan Ikhtisar Realisasi Kinerja SKPD','Kumulatif','Jumlah Laporan Capaian Kinerja dan Ikhtisar Realisasi Kinerja SKPD serta Laporan Hasil Koordinasi Penyusunan Laporan Capaian Kinerja dan Ikhtisar Realisasi Kinerja SKPD adalah jumlah laporan yang disusun oleh Satuan Kerja Perangkat Daerah (SKPD) mengenai capaian indikator kinerja, realisasi pelaksanaan program, kegiatan dan subkegiatan, realisasi anggaran, serta laporan hasil koordinasi dalam proses penyusunan laporan kinerja yang telah diselesaikan dan disampaikan sesuai ketentuan dalam satu tahun anggaran.Laporan tersebut merupakan dokumen yang digunakan sebagai media pertanggungjawaban pelaksanaan kinerja perangkat daerah sekaligus sebagai bahan evaluasi terhadap pencapaian target yang telah ditetapkan dalam dokumen perencanaan dan perjanjian kinerja.','Sekretariat','Sekretaris'),
('01-03-02-01-03-01','01-03-02-01-03','01','Jumlah Laporan Evaluasi Kinerja Perangkat daerah','Dokumen','0','7','7','7','7','7','indikator ini dipilih untuk mengetahui Jumlah Laporan Evaluasi Kinerja Perangkat daerah','Jumlah Laporan Evaluasi Kinerja Perangkat daerah','Kumulatif','Jumlah Laporan Evaluasi Kinerja Perangkat Daerah adalah jumlah dokumen laporan yang disusun oleh perangkat daerah sebagai hasil kegiatan evaluasi terhadap pencapaian kinerja pelaksanaan program, kegiatan, subkegiatan, indikator kinerja, serta realisasi anggaran dalam suatu periode tertentu yang telah diselesaikan dan disampaikan sesuai ketentuan peraturan perundang-undangan dalam satu tahun anggaran.Laporan evaluasi kinerja disusun sebagai bentuk pengukuran dan penilaian atas tingkat keberhasilan pelaksanaan tugas dan fungsi perangkat daerah, sekaligus sebagai dasar dalam penyusunan rekomendasi perbaikan, peningkatan kinerja, pengambilan keputusan, dan penyusunan perencanaan pada periode berikutnya.','Sekretariat','Sekretaris');
